/* STEP Foundation — Grammar, Unit 2 (original material by Waleed Youssef) */
(window.STEP_BOOK = window.STEP_BOOK || {})["G2"] = {"n":2,"level":"A2","t":"Past, Future and Comparison","lessons":[{"id":"2.1","t":"Past Simple of be (was / were)","html":"<p><strong>Unit 2 · Lesson 2.1 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Form was / were in positive, negative and question sentences, with short answers.</p>\n<p>2. Use past time expressions (yesterday, last week, two days ago, in 2019).</p>\n<p>3. Choose was or were correctly with you, plural subjects and there was / there were.</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يكوّن الطالب was وwere في الإثبات والنفي والسؤال مع الإجابات القصيرة.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يستخدم تعبيرات الزمن الماضي مثل yesterday وlast week وago.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يختار was أو were بشكل صحيح مع you والجمع ومع there was وthere were.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. I ______ at home yesterday.</strong></p>\n<blockquote>\n<p>A. were B. was C. am D. be</p>\n</blockquote>\n<p><strong>2. My friends ______ at the match last night.</strong></p>\n<blockquote>\n<p>A. was B. is C. were D. be</p>\n</blockquote>\n<p><strong>3. There ______ a lot of people at the mall.</strong></p>\n<blockquote>\n<p>A. were B. was C. is D. has</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>Positive</strong></p>\n<p><strong>I / he / she / it + was · you / we / they + were</strong></p>\n<p><em>e.g. I was tired. They were in Makkah.</em></p>\n<p><strong>Negative</strong></p>\n<p><strong>was not (wasn't) · were not (weren't)</strong></p>\n<p><em>e.g. She wasn't at school. We weren't late.</em></p>\n<p><strong>Yes / No questions</strong></p>\n<p><strong>Was / Were + subject + …?</strong></p>\n<p><em>e.g. Was the film good? Were you at home?</em></p>\n<p><strong>Short answers</strong></p>\n<p><strong>Yes, I was. / No, I wasn't. · Yes, they were. / No, they weren't.</strong></p>\n<p><em>e.g. Were they happy? Yes, they were.</em></p>\n<p><strong>Wh- questions</strong></p>\n<p><strong>Wh- word + was / were + subject …?</strong></p>\n<p><em>e.g. Where were you last night? Why was he angry?</em></p>\n<p><strong>there was / there were</strong></p>\n<p><strong>there was + singular / uncountable · there were + plural</strong></p>\n<p><em>e.g. There was a storm. There were many cars.</em></p>\n<p><strong>Past time expressions</strong></p>\n<p><strong>yesterday · last night / week / year · two days ago · in 2019 · when I was a child</strong></p>\n<p><em>e.g. I was in Dubai two weeks ago.</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. Past states, places and feelings.</strong></p>\n<p>We use was / were to talk about where someone was, how they felt, or what something was like in the past.</p>\n<blockquote>\n<p>▸ I was in Abha last summer.</p>\n<p>▸ The weather was cool and rainy.</p>\n<p>▸ My grandparents were very happy to see us.</p>\n<p>▸ The test wasn't difficult.</p>\n</blockquote>\n<p><strong>2. Age, jobs and descriptions in the past.</strong></p>\n<p>We use was / were for past facts about people and things.</p>\n<blockquote>\n<p>▸ My father was a teacher for twenty years.</p>\n<p>▸ When I was six, I was very shy.</p>\n<p>▸ Our old house was small, but it was near the sea.</p>\n</blockquote>\n<p><strong>3. Asking about the past.</strong></p>\n<p>Questions put was / were before the subject.</p>\n<blockquote>\n<p>▸ Was your trip to Hail nice?</p>\n<p>▸ Where were your keys?</p>\n<p>▸ How was the concert?</p>\n</blockquote>\n<p><strong>4. there was / there were.</strong></p>\n<p>We use them to say what existed in the past.</p>\n<blockquote>\n<p>▸ There was a big storm last night.</p>\n<p>▸ There were twenty students in the room.</p>\n<p>▸ There wasn't any water in the bottle.</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ you is always were, even for one person: You were right. (not You was)</p>\n<p>▸ ago comes after the time phrase: three days ago (not ago three days).</p>\n<p>▸ No preposition before yesterday, last, ago: I was there last week. (not in last week)</p>\n<p>▸ Two subjects joined by and are plural: My brother and I were …</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الماضي من فعل be له صورتان: was مع I وhe وshe وit والاسم المفرد، وwere مع you وwe وthey والاسم الجمع. ونستخدمهما للحديث عن الأماكن والمشاعر والأوصاف في الماضي.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">في النفي نقول wasn't وweren't، وفي السؤال نقدّم was أو were على الفاعل. ومع there نقول there was للمفرد وغير المعدود، وthere were للجمع.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">من كلمات الزمن الماضي: yesterday وlast week وtwo days ago وin 2019، ولا نضع حرف جر قبل yesterday وlast، وتأتي ago بعد المدة.</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>You was late.</em> <strong>→ ✓ You were late.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">you تأخذ were دائمًا.</span></p>\n<p><strong>✗</strong> <em>They was at home.</em> <strong>→ ✓ They were at home.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">they جمع فتأخذ were.</span></p>\n<p><strong>✗</strong> <em>I was go to school yesterday.</em> <strong>→ ✓ I went to school yesterday.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا نضع was قبل الفعل الأساسي في الماضي البسيط.</span></p>\n<p><strong>✗</strong> <em>before two days</em> <strong>→ ✓ two days ago</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">«قبل يومين» تُترجم two days ago.</span></p>\n<p><strong>✗</strong> <em>in last week</em> <strong>→ ✓ last week</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا حرف جر قبل last.</span></p>\n<p><strong>✗</strong> <em>There was many people.</em> <strong>→ ✓ There were many people.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الاسم الجمع يأخذ there were.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>Present: I am tired today. / They are at school now.</p>\n<p>Past: I was tired yesterday. / They were at school yesterday.</p>\n<p>was ↔︎ is / am · were ↔︎ are</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. Find the subject: I, he, she, it or a singular noun → was; you, we, they or a plural noun → were.</p>\n<p>2. Look for past time words (yesterday, last, ago) to choose past instead of present.</p>\n<p>3. For there was / were, check the noun AFTER the verb.</p>\n<p>4. A sentence like I was go is a common error — was cannot sit before a main verb in the past simple.</p>\n<p>5. In error identification, check ago, last and yesterday for extra prepositions.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">حدّد الفاعل لتختار was أو were، وابحث عن كلمات الزمن الماضي، ومع there انظر إلى الاسم الذي بعد الفعل، وتذكّر أن you تأخذ were دائمًا.</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. You ______ right about the weather. It rained all day.</strong></p>\n<blockquote>\n<p>A. was B. were C. are D. is</p>\n<p><strong>Step 1:</strong> It rained all day shows past time.</p>\n<p><strong>Step 2:</strong> you always takes were.</p>\n<p><strong>Step 3:</strong> The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">you تأخذ were دائمًا في الماضي.</span></p>\n<p><strong>Example 2. There ______ a lot of traffic on the way to the airport this morning.</strong></p>\n<blockquote>\n<p>A. were B. are C. was D. have</p>\n<p><strong>Step 1:</strong> this morning (finished) is past time.</p>\n<p><strong>Step 2:</strong> traffic is uncountable, so there was.</p>\n<p><strong>Step 3:</strong> The answer is C.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">traffic غير معدودة والزمن ماضٍ فنستخدم there was.</span></p>\n<p><strong>Example 3. My (A) <u>cousins</u> (B) <u>was</u> at our house (C) <u>two days</u> (D) <u>ago</u>.</strong></p>\n<blockquote>\n<p>A. cousins B. was C. two days D. ago</p>\n<p><strong>Step 1:</strong> The subject My cousins is plural.</p>\n<p><strong>Step 2:</strong> Plural subjects take were.</p>\n<p><strong>Step 3:</strong> Correct: My cousins were at our house two days ago. The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الفاعل جمع فيأخذ were.</span></p>","wu":"Warm-up: 1 B · 2 C · 3 A · Worked examples: Example 1 B · Example 2 C · Example 3 B","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"I ______ at the dentist yesterday afternoon.","o":["were","was","am","is"],"k":1,"e":"I + past → was.","h":"I في الماضي تأخذ was."},{"n":2,"s":"My parents ______ in Madinah last week.","o":["was","are","were","is"],"k":2,"e":"My parents is plural → were.","h":"الفاعل جمع فيأخذ were."},{"n":3,"s":"The weather ______ very cold last night.","o":["were","is","was","be"],"k":2,"e":"The weather is singular; last night → was.","h":"مفرد في الماضي."},{"n":4,"s":"______ you at the football match on Friday?","o":["Were","Was","Are","Did"],"k":0,"e":"you → Were in past questions.","h":"you تأخذ Were."},{"n":5,"s":"The film wasn't long. It ______ only ninety minutes.","o":["were","is","be","was"],"k":3,"e":"It + past → was.","h":"It تأخذ was."},{"n":6,"s":"We ______ at school yesterday because it was a holiday.","o":["wasn't","aren't","weren't","didn't"],"k":2,"e":"we + negative past → weren't.","h":"we في النفي weren't."},{"n":7,"s":"There ______ two cats in the garden this morning.","o":["was","are","is","were"],"k":3,"e":"two cats is plural → There were.","h":"الاسم جمع فنستخدم were."},{"n":8,"s":"My grandfather ______ a farmer when he was young.","o":["were","is","be","was"],"k":3,"e":"My grandfather → was.","h":"مفرد فيأخذ was."},{"n":9,"s":"I visited Abha three years ______.","o":["ago","before","last","since"],"k":0,"e":"Time phrase + ago for past time.","h":"المدة ثم ago."},{"n":10,"s":"\"Was the exam easy?\" \"No, it ______.\"","o":["weren't","isn't","didn't","wasn't"],"k":3,"e":"Short answer for Was it …? → No, it wasn't.","h":"الإجابة القصيرة No, it wasn't."},{"n":11,"s":"Where ______ your brothers last night?","o":["was","were","are","did"],"k":1,"e":"your brothers is plural → were.","h":"الفاعل جمع."},{"n":12,"s":"There ______ any milk in the fridge, so I went to the shop.","o":["weren't","isn't","wasn't","aren't"],"k":2,"e":"milk is uncountable; past negative → wasn't.","h":"milk غير معدودة."},{"n":13,"s":"My sister and I ______ very tired after the long journey.","o":["were","was","am","is"],"k":0,"e":"My sister and I = we → were.","h":"الفاعل المركب جمع."},{"n":14,"s":"We were in Taif ______ summer.","o":["in last","on last","the last","last"],"k":3,"e":"No preposition before last.","h":"لا حرف جر قبل last."},{"n":15,"s":"How ______ your holiday in Al-Ula? Did you enjoy it?","o":["were","is","did","was"],"k":3,"e":"your holiday is singular → How was …?","h":"الاسم مفرد."},{"n":16,"s":"\"Were the questions difficult?\" \"Yes, they ______.\"","o":["was","did","were","are"],"k":2,"e":"Short answer: Yes, they were.","h":"الإجابة القصيرة Yes, they were."},{"n":17,"s":"When I ______ a child, I was afraid of the dark.","o":["were","am","had","was"],"k":3,"e":"I + past → was.","h":"I تأخذ was."},{"n":18,"s":"Everybody in the hall ______ quiet when the speaker started.","o":["were","was","are","be"],"k":1,"e":"Everybody is singular → was.","h":"Everybody مفرد."},{"n":19,"s":"Why ______ the shops closed yesterday?","o":["was","were","did","are"],"k":1,"e":"the shops is plural; past → were.","h":"الفاعل جمع والزمن ماضٍ."},{"n":20,"s":"The news about the new stadium ______ exciting.","o":["was","were","are","have been"],"k":0,"e":"news is singular uncountable → was.","h":"news مفردة."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"I (A) was very (B) happy (C) in (D) yesterday evening.","o":["was","happy","in","yesterday"],"k":2,"e":"No preposition before yesterday.","h":""},{"n":22,"s":"The (A) students (B) was in (C) the library (D) last Monday.","o":["students","was","the","last"],"k":1,"e":"The students is plural → were.","h":""},{"n":23,"s":"(A) Was you at (B) home when (C) I (D) called?","o":["Was","home","I","called"],"k":0,"e":"you → Were.","h":""},{"n":24,"s":"There (A) was many (B) people at (C) the (D) festival.","o":["was","people","the","festival"],"k":0,"e":"many people is plural → There were.","h":""},{"n":25,"s":"My (A) uncle (B) was (C) a pilot (D) before ten years.","o":["uncle","was","a pilot","before ten years"],"k":3,"e":"The English phrase is ten years ago.","h":""},{"n":26,"s":"We (A) weren't at (B) the park because it (C) were too (D) hot.","o":["weren't","the","were","hot"],"k":2,"e":"it → was.","h":""},{"n":27,"s":"(A) Where (B) was your (C) parents (D) last night?","o":["Where","was","parents","last"],"k":1,"e":"your parents is plural → were.","h":""},{"n":28,"s":"I (A) was (B) go to (C) the dentist (D) on Tuesday.","o":["was","go","the","on"],"k":1,"e":"was cannot come before a main verb; the past of go is went.","h":""},{"n":29,"s":"My brother and (A) me (B) were (C) in the same class (D) last year.","o":["me","were","in","last"],"k":0,"e":"Part of the subject → I.","h":""},{"n":30,"s":"The (A) weather in Jeddah (B) were (C) very humid (D) last week.","o":["weather","were","very","last"],"k":1,"e":"The weather is singular → was.","h":""}]}],"n":30},{"id":"2.2","t":"Past Simple: Regular and Irregular Verbs","html":"<p><strong>Unit 2 · Lesson 2.2 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Spell regular past forms correctly (-ed, -d, -ied, doubled consonants).</p>\n<p>2. Use common irregular past forms (see Appendix A).</p>\n<p>3. Use did + base form in negatives and questions and avoid errors such as didn't went.</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يكتب الطالب صيغة الماضي المنتظم بتهجئة صحيحة.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يستخدم صيغ الماضي الشاذة الشائعة (انظر الملحق أ).</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يستخدم did مع الفعل الأصلي في النفي والسؤال ويتجنب أخطاء مثل didn't went.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. We ______ football yesterday afternoon.</strong></p>\n<blockquote>\n<p>A. play B. plays C. played D. playing</p>\n</blockquote>\n<p><strong>2. I ______ my keys at school last week.</strong></p>\n<blockquote>\n<p>A. lost B. losed C. lose D. loses</p>\n</blockquote>\n<p><strong>3. ______ you see the match last night?</strong></p>\n<blockquote>\n<p>A. Do B. Did C. Were D. Was</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>Positive (regular)</strong></p>\n<p><strong>Subject + verb + -ed (same for all subjects)</strong></p>\n<p><em>e.g. I visited my uncle. She cleaned her room.</em></p>\n<p><strong>Positive (irregular)</strong></p>\n<p><strong>Subject + past form (learn it: go → went, eat → ate, buy → bought)</strong></p>\n<p><em>e.g. We went to Taif. He bought a new phone.</em></p>\n<p><strong>Negative</strong></p>\n<p><strong>Subject + didn't (did not) + base verb</strong></p>\n<p><em>e.g. They didn't call me. She didn't go out.</em></p>\n<p><strong>Yes / No questions</strong></p>\n<p><strong>Did + subject + base verb …? — Yes, I did. / No, he didn't.</strong></p>\n<p><em>e.g. Did you finish your homework? Yes, I did.</em></p>\n<p><strong>Wh- questions</strong></p>\n<p><strong>Wh- word + did + subject + base verb …?</strong></p>\n<p><em>e.g. Where did you go? What did she buy?</em></p>\n<p><strong>Spelling: -e → -d</strong></p>\n<p><strong>live → lived · arrive → arrived · smile → smiled</strong></p>\n<p><em>e.g. We arrived late.</em></p>\n<p><strong>Spelling: consonant + y → -ied</strong></p>\n<p><strong>study → studied · carry → carried · try → tried (but play → played)</strong></p>\n<p><em>e.g. She studied all night.</em></p>\n<p><strong>Spelling: short vowel + consonant → double</strong></p>\n<p><strong>stop → stopped · plan → planned · drop → dropped</strong></p>\n<p><em>e.g. The bus stopped suddenly.</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. Finished actions at a past time.</strong></p>\n<p>We use the past simple for actions that started and finished in the past, often with a time word.</p>\n<blockquote>\n<p>▸ I watched a documentary last night.</p>\n<p>▸ My father bought a new car in 2023.</p>\n<p>▸ We visited the National Museum two weeks ago.</p>\n</blockquote>\n<p><strong>2. A series of past actions.</strong></p>\n<p>We use it to tell what happened, one action after another.</p>\n<blockquote>\n<p>▸ I woke up, had breakfast and took the bus to school.</p>\n<p>▸ He opened the door, looked inside and smiled.</p>\n<p>▸ We arrived at the hotel, left our bags and went to the beach.</p>\n</blockquote>\n<p><strong>3. Past habits (with a time period).</strong></p>\n<p>We can use it for repeated past actions.</p>\n<blockquote>\n<p>▸ When I lived in Dammam, I swam in the sea every week.</p>\n<p>▸ My grandfather walked to work every day.</p>\n<p>▸ As a child, Noura read a story every night.</p>\n</blockquote>\n<p><strong>4. Negatives and questions with did.</strong></p>\n<p>did carries the past meaning, so the main verb returns to the base form.</p>\n<blockquote>\n<p>▸ She didn't like the food.</p>\n<p>▸ Did they win the match?</p>\n<p>▸ What time did you wake up?</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ Pronunciation of -ed: /t/ after p, k, s, sh, ch (stopped, walked) · /d/ after other voiced sounds (played) · /ɪd/ after t or d (visited, needed).</p>\n<p>▸ Common irregular verbs: go–went, come–came, see–saw, eat–ate, drink–drank, buy–bought, think–thought, take–took, make–made, write–wrote (Appendix A).</p>\n<p>▸ Never use the past form after did: ✗ Did you saw? ✓ Did you see?</p>\n<p>▸ Time words: yesterday, last …, … ago, in 2020, when I was young.</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">نستخدم الماضي البسيط لحدث بدأ وانتهى في الماضي، ونكوّنه بإضافة ed إلى الفعل المنتظم مثل visited، أما الأفعال الشاذة فلها صيغ خاصة يجب حفظها مثل went وbought.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">في النفي نستخدم didn't ثم الفعل في صورته الأصلية، وفي السؤال نبدأ بـ Did ثم الفاعل ثم الفعل في صورته الأصلية؛ لأن did تحمل معنى الماضي.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">انتبه للتهجئة: نضيف d فقط إذا انتهى الفعل بـ e، ونحوّل y إلى ied بعد الحرف الساكن، ونضاعف الحرف الأخير في مثل stop فيصبح stopped.</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>I didn't went to school.</em> <strong>→ ✓ I didn't go to school.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد didn't يأتي الفعل الأصلي.</span></p>\n<p><strong>✗</strong> <em>Did you saw the news?</em> <strong>→ ✓ Did you see the news?</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد Did يأتي الفعل الأصلي.</span></p>\n<p><strong>✗</strong> <em>He buyed a new phone.</em> <strong>→ ✓ He bought a new phone.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">buy فعل شاذ ماضيه bought.</span></p>\n<p><strong>✗</strong> <em>She studyed hard.</em> <strong>→ ✓ She studied hard.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">y بعد حرف ساكن تتحول إلى ied.</span></p>\n<p><strong>✗</strong> <em>I was visited my uncle.</em> <strong>→ ✓ I visited my uncle.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا نضع was قبل الفعل في الماضي البسيط.</span></p>\n<p><strong>✗</strong> <em>Where you went yesterday?</em> <strong>→ ✓ Where did you go yesterday?</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">السؤال يحتاج did والفعل الأصلي.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>Positive: She went home. · Negative: She didn't go home. · Question: Did she go home?</p>\n<p>Regular: play → played · Irregular: go → went</p>\n<p>did + base: did go · did eat · did buy</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. Look for past time words (yesterday, ago, last) to choose the past simple.</p>\n<p>2. After did / didn't, choose the BASE form, never the past form.</p>\n<p>3. Check spelling of -ed forms: studied, stopped, arrived.</p>\n<p>4. Know the common irregular verbs (Appendix A) — STEP often uses buyed, goed, catched as distractors.</p>\n<p>5. In Wh- questions, check for did and the base verb.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">ابحث عن كلمات الزمن الماضي، وتذكّر أن الفعل بعد did وdidn't يكون في صورته الأصلية، واحفظ الأفعال الشاذة الشائعة، وراجع تهجئة ed.</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. My brother ______ his phone on the bus yesterday.</strong></p>\n<blockquote>\n<p>A. leaves B. leaved C. left D. leaving</p>\n<p><strong>Step 1:</strong> yesterday → past simple.</p>\n<p><strong>Step 2:</strong> leave is irregular: leave → left.</p>\n<p><strong>Step 3:</strong> The answer is C.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">leave فعل شاذ ماضيه left.</span></p>\n<p><strong>Example 2. What time ______ the plane land last night?</strong></p>\n<blockquote>\n<p>A. did B. does C. was D. landed</p>\n<p><strong>Step 1:</strong> last night → past.</p>\n<p><strong>Step 2:</strong> A Wh- question with a main verb (land) needs did.</p>\n<p><strong>Step 3:</strong> The answer is A.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">السؤال في الماضي مع فعل رئيس يحتاج did.</span></p>\n<p><strong>Example 3. We (A) <u>didn't</u> (B) <u>found</u> the (C) <u>hotel</u> (D) <u>easily</u> because it was dark.</strong></p>\n<blockquote>\n<p>A. didn't B. found C. hotel D. easily</p>\n<p><strong>Step 1:</strong> After didn't we need the base form.</p>\n<p><strong>Step 2:</strong> found is the past form; the base form is find.</p>\n<p><strong>Step 3:</strong> Correct: We didn't find the hotel easily because it was dark. The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد didn't نستخدم find لا found.</span></p>","wu":"Warm-up: 1 C · 2 A · 3 B · Worked examples: Example 1 C · Example 2 A · Example 3 B","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"I ______ my grandparents last Friday.","o":["visit","visits","visiting","visited"],"k":3,"e":"last Friday → past simple: visited.","h":"last Friday تدل على الماضي."},{"n":2,"s":"We ______ to the beach two days ago.","o":["go","went","goed","gone"],"k":1,"e":"go → went (irregular).","h":"ماضي go هو went."},{"n":3,"s":"She ______ the bus this morning because she woke up late.","o":["miss","misses","missed","missd"],"k":2,"e":"Past simple, regular: missed.","h":"الماضي المنتظم missed."},{"n":4,"s":"My father ______ a new laptop for me last month.","o":["buyed","buy","brought","bought"],"k":3,"e":"buy → bought.","h":"ماضي buy هو bought."},{"n":5,"s":"I ______ like the film. It was boring.","o":["don't","wasn't","didn't","not"],"k":2,"e":"Past negative → didn't + base verb.","h":"النفي في الماضي didn't."},{"n":6,"s":"______ you finish your project yesterday?","o":["Did","Do","Were","Have"],"k":0,"e":"Past question with a main verb → Did.","h":"السؤال في الماضي Did."},{"n":7,"s":"The children ______ a lot of water after the game.","o":["drinked","drink","drank","drunk"],"k":2,"e":"drink → drank.","h":"ماضي drink هو drank."},{"n":8,"s":"Huda ______ hard for her final exams.","o":["studied","studyed","studies","study"],"k":0,"e":"Consonant + y → -ied: studied.","h":"y بعد ساكن تصبح ied."},{"n":9,"s":"The car ______ suddenly at the traffic lights.","o":["stopped","stoped","stops","stop"],"k":0,"e":"stop doubles the p: stopped.","h":"نضاعف p في stopped."},{"n":10,"s":"They didn't ______ the answer to the last question.","o":["knew","knows","know","known"],"k":2,"e":"After didn't → base form know.","h":"بعد didn't الفعل الأصلي."},{"n":11,"s":"Where ______ you buy those shoes?","o":["do","were","are","did"],"k":3,"e":"Past Wh- question → did.","h":"السؤال في الماضي did."},{"n":12,"s":"I ______ an email to my teacher last night.","o":["writed","wrote","write","written"],"k":1,"e":"write → wrote.","h":"ماضي write هو wrote."},{"n":13,"s":"\"Did you enjoy the trip?\" \"Yes, I ______.\"","o":["enjoyed","did","do","was"],"k":1,"e":"Short answer: Yes, I did.","h":"الإجابة القصيرة Yes, I did."},{"n":14,"s":"We ______ in a small village when I was a child.","o":["liveed","live","living","lived"],"k":3,"e":"live ends in -e → add -d: lived.","h":"نضيف d فقط."},{"n":15,"s":"The teacher ______ us a funny story yesterday.","o":["told","telled","tell","said"],"k":0,"e":"tell → told; said does not take an object like us.","h":"ماضي tell هو told."},{"n":16,"s":"My mother ______ the shopping bags into the kitchen.","o":["carryed","carrys","carry","carried"],"k":3,"e":"Consonant + y → -ied: carried.","h":"carried بالتهجئة الصحيحة."},{"n":17,"s":"What ______ you have for breakfast this morning?","o":["do","were","had","did"],"k":3,"e":"Past question (this morning, finished) → did.","h":"السؤال عن الماضي."},{"n":18,"s":"Ahmad ______ his leg when he fell off his bike.","o":["hurt","hurted","hurts","hurting"],"k":0,"e":"hurt → hurt (same form).","h":"hurt لا يتغير."},{"n":19,"s":"They ______ the plan and started the project in June.","o":["planed","plan","planned","planing"],"k":2,"e":"plan doubles the n: planned.","h":"نضاعف n."},{"n":20,"s":"How long ago ______ your family move to Riyadh?","o":["was","has","does","did"],"k":3,"e":"A past question with move → did.","h":"السؤال في الماضي did."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"I (A) didn't (B) went to (C) the gym (D) last week.","o":["didn't","went","the","last"],"k":1,"e":"After didn't → base form go.","h":""},{"n":22,"s":"Yesterday my (A) brother (B) went fishing and (C) catched a (D) big fish.","o":["brother","went","catched","big"],"k":2,"e":"catch → caught.","h":""},{"n":23,"s":"(A) Did your sister (B) saw the (C) new (D) museum?","o":["Did","saw","new","museum"],"k":1,"e":"After Did → base form see.","h":""},{"n":24,"s":"We (A) arrived at (B) the airport (C) before two (D) hours.","o":["arrived","the","before","hours"],"k":2,"e":"For past time we use two hours ago.","h":""},{"n":25,"s":"She (A) was (B) cooked dinner (C) for the family (D) last night.","o":["was","cooked","for","last"],"k":0,"e":"was is not used with the past simple of cook.","h":""},{"n":26,"s":"(A) Where you (B) spent your (C) holiday (D) last summer?","o":["Where","spent","holiday","last"],"k":1,"e":"The question needs did + base verb spend.","h":""},{"n":27,"s":"He (A) tryed (B) to call you, but your phone (C) was (D) off.","o":["tryed","to call","was","off"],"k":0,"e":"try → tried.","h":""},{"n":28,"s":"The (A) children (B) sleeped (C) early because they (D) were tired.","o":["children","sleeped","early","were"],"k":1,"e":"sleep → slept.","h":""},{"n":29,"s":"Our (A) team (B) won the match, but we (C) didn't (D) scored many goals.","o":["team","won","didn't","scored"],"k":3,"e":"After didn't → base form score.","h":""},{"n":30,"s":"I (A) readed (B) an interesting (C) article about space (D) last night.","o":["readed","an","article","last"],"k":0,"e":"read → read (same spelling, different sound).","h":""}]}],"n":30},{"id":"2.3","t":"Future Forms: will, be going to and Present Continuous for Arrangements","html":"<p><strong>Unit 2 · Lesson 2.3 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Use will for predictions, promises, offers and instant decisions.</p>\n<p>2. Use be going to for plans and for predictions based on present evidence.</p>\n<p>3. Use the present continuous for fixed arrangements with a time and place.</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يستخدم الطالب will للتوقع والوعد والعرض والقرار اللحظي.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يستخدم be going to للخطط وللتوقع المبني على دليل حاضر.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يستخدم المضارع المستمر للترتيبات المؤكدة ذات الوقت والمكان المحددين.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. Look at those black clouds. It ______ rain.</strong></p>\n<blockquote>\n<p>A. will B. is going to C. is raining D. rains</p>\n</blockquote>\n<p><strong>2. \"The phone is ringing.\" \"I ______ answer it.\"</strong></p>\n<blockquote>\n<p>A. will B. am going to C. am answering D. answer</p>\n</blockquote>\n<p><strong>3. We ______ our cousins tomorrow at 6 p.m. It's all arranged.</strong></p>\n<blockquote>\n<p>A. visit B. will visiting C. are visiting D. visited</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>will</strong></p>\n<p><strong>Subject + will ('ll) + base verb · won't (will not) + base verb</strong></p>\n<p><em>e.g. I'll help you. It won't take long.</em></p>\n<p><strong>will — questions</strong></p>\n<p><strong>Will + subject + base verb …? — Yes, I will. / No, I won't.</strong></p>\n<p><em>e.g. Will you be home tonight? Yes, I will.</em></p>\n<p><strong>be going to</strong></p>\n<p><strong>Subject + am / is / are + going to + base verb</strong></p>\n<p><em>e.g. We are going to travel next week.</em></p>\n<p><strong>be going to — negative and questions</strong></p>\n<p><strong>isn't / aren't going to · Is / Are + subject + going to …?</strong></p>\n<p><em>e.g. She isn't going to come. Are you going to study?</em></p>\n<p><strong>Present continuous (future)</strong></p>\n<p><strong>Subject + am / is / are + verb-ing + future time</strong></p>\n<p><em>e.g. I'm meeting Sami at 5 tomorrow.</em></p>\n<p><strong>Future time words</strong></p>\n<p><strong>tomorrow · next week / month / year · tonight · this evening · in two days · soon</strong></p>\n<p><em>e.g. We're flying to Abha in two days.</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. will: predictions (opinion), promises and offers.</strong></p>\n<p>We use will for what we think or believe about the future, and to promise or offer.</p>\n<blockquote>\n<p>▸ I think it will be sunny tomorrow.</p>\n<p>▸ I promise I'll call you when I arrive.</p>\n<p>▸ That bag looks heavy. I'll carry it for you.</p>\n</blockquote>\n<p><strong>2. will: instant decisions.</strong></p>\n<p>We use will when we decide at the moment of speaking.</p>\n<blockquote>\n<p>▸ \"We're out of milk.\" \"OK, I'll buy some.\"</p>\n<p>▸ I'm tired. I think I'll go to bed early.</p>\n</blockquote>\n<p><strong>3. be going to: plans and intentions.</strong></p>\n<p>We use be going to for things we decided before speaking.</p>\n<blockquote>\n<p>▸ I'm going to study medicine at university.</p>\n<p>▸ My parents are going to paint the house next month.</p>\n<p>▸ What are you going to do this summer?</p>\n</blockquote>\n<p><strong>4. be going to: predictions with present evidence.</strong></p>\n<p>When we can see something now that shows the future, we use be going to.</p>\n<blockquote>\n<p>▸ Look at the sky. It's going to rain.</p>\n<p>▸ Be careful! You're going to drop the glasses.</p>\n</blockquote>\n<p><strong>5. Present continuous: fixed arrangements.</strong></p>\n<p>For plans with a time, a place or other people already arranged, we often use the present continuous.</p>\n<blockquote>\n<p>▸ I'm seeing the doctor at 4 o'clock tomorrow.</p>\n<p>▸ We're having dinner with our cousins on Thursday.</p>\n<p>▸ My uncle is arriving from Cairo tonight.</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ Do not use will after when / if / before / after / as soon as for the future: When he arrives, I'll call you. (not when he will arrive)</p>\n<p>▸ I think … will is common for opinions; I don't think … will is better than I think … won't.</p>\n<p>▸ gonna is informal speech only; write going to.</p>\n<p>▸ Shall I …? / Shall we …? = offers and suggestions (Shall I open the window?).</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">نستخدم will للتوقع المبني على الرأي، وللوعد، وللعرض، وللقرار الذي نتخذه في لحظة الكلام، ويأتي بعدها الفعل في صورته الأصلية دائمًا.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">نستخدم be going to للخطة التي قررناها مسبقًا، وللتوقع المبني على دليل نراه الآن، مثل السحب السوداء قبل المطر.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">ونستخدم المضارع المستمر للمستقبل عندما يكون الأمر مرتبًا ومحددًا بوقت ومكان، مثل I'm meeting Sami at 5 tomorrow.</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>I will to call you.</em> <strong>→ ✓ I will call you.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا نضع to بعد will.</span></p>\n<p><strong>✗</strong> <em>She will goes to Riyadh.</em> <strong>→ ✓ She will go to Riyadh.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد will الفعل الأصلي دون s.</span></p>\n<p><strong>✗</strong> <em>I going to study.</em> <strong>→ ✓ I am going to study.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا بد من am/is/are قبل going to.</span></p>\n<p><strong>✗</strong> <em>When I will arrive, I will call you.</em> <strong>→ ✓ When I arrive, I will call you.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد when نستخدم المضارع للمستقبل.</span></p>\n<p><strong>✗</strong> <em>Look! The glass will fall.</em> <strong>→ ✓ Look! The glass is going to fall.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الدليل الحاضر يتطلب going to.</span></p>\n<p><strong>✗</strong> <em>Tomorrow I travel to Jeddah at 6. (arranged)</em> <strong>→ ✓ Tomorrow I'm travelling to Jeddah at 6.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الترتيب المحدد يستخدم المضارع المستمر.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>Instant decision: \"It's cold.\" \"I'll close the window.\"</p>\n<p>Plan made before: I'm going to close the shop early today.</p>\n<p>Arrangement with time: I'm closing the shop at 3 p.m. — the manager knows.</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. Ask: Is it a decision NOW (will), a plan made BEFORE (going to), or an arrangement with a time (present continuous)?</p>\n<p>2. Evidence in the sentence (Look!, black clouds) → going to.</p>\n<p>3. Promises, offers, opinions (I think, probably) → will.</p>\n<p>4. After will, never add -s or to; after going to, use the base verb.</p>\n<p>5. No will after when / if / as soon as in future time clauses.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">اسأل نفسك: هل القرار الآن (will)، أم خطة سابقة (going to)، أم ترتيب محدد بوقت (المضارع المستمر)؟ وإذا وُجد دليل حاضر فاختر going to.</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. \"I can't open this jar.\" \"Give it to me. I ______ open it for you.\"</strong></p>\n<blockquote>\n<p>A. am going to B. will C. am opening D. open</p>\n<p><strong>Step 1:</strong> The speaker decides to help at the moment of speaking.</p>\n<p><strong>Step 2:</strong> Instant decision / offer → will.</p>\n<p><strong>Step 3:</strong> The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">قرار لحظي وعرض مساعدة فنستخدم will.</span></p>\n<p><strong>Example 2. Hamad has bought paint and brushes. He ______ his bedroom this weekend.</strong></p>\n<blockquote>\n<p>A. will paint B. paints</p>\n<p>C. painted D. is going to paint</p>\n<p><strong>Step 1:</strong> He has already bought the paint — the plan was made before.</p>\n<p><strong>Step 2:</strong> Plan / intention → be going to.</p>\n<p><strong>Step 3:</strong> The answer is D.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الخطة مقررة مسبقًا فنستخدم going to.</span></p>\n<p><strong>Example 3. (A) <u>When</u> my father (B) <u>will come</u> home, we (C) <u>are going to</u> (D) <u>have</u> dinner together.</strong></p>\n<blockquote>\n<p>A. When B. will come C. are going to D. have</p>\n<p><strong>Step 1:</strong> After when in a future sentence, we use the present simple.</p>\n<p><strong>Step 2:</strong> will come must be comes.</p>\n<p><strong>Step 3:</strong> Correct: When my father comes home, we are going to have dinner together. The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد when نستخدم المضارع البسيط للمستقبل.</span></p>","wu":"Warm-up: 1 B · 2 A · 3 C · Worked examples: Example 1 B · Example 2 D · Example 3 B","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"I think our team ______ the match tomorrow.","o":["will win","wins","is winning","won"],"k":0,"e":"An opinion about the future (I think) → will.","h":"رأي عن المستقبل will."},{"n":2,"s":"\"I'm thirsty.\" \"I ______ get you some water.\"","o":["am going to","get","'ll","'m getting"],"k":2,"e":"Instant offer → will ('ll).","h":"عرض لحظي will."},{"n":3,"s":"We ______ visit Al-Ula next month. We booked the hotel last week.","o":["will to","are going to","going to","are go to"],"k":1,"e":"A plan made before (booked) → are going to.","h":"خطة سابقة going to."},{"n":4,"s":"Look out! That glass ______ fall off the table.","o":["will","falls","is going to","goes to"],"k":2,"e":"Present evidence (Look out!) → is going to.","h":"دليل حاضر going to."},{"n":5,"s":"My sister ______ married next Thursday. The invitations are ready.","o":["is getting","gets","will getting","get"],"k":0,"e":"A fixed arrangement → present continuous.","h":"ترتيب مؤكد بالمستمر."},{"n":6,"s":"I promise I ______ tell anyone your secret.","o":["don't","am not","won't","willn't"],"k":2,"e":"A promise in the negative → won't.","h":"الوعد المنفي won't."},{"n":7,"s":"\"What are your plans for the summer?\" \"I ______ learn to swim.\"","o":["will to","'m going to","'m go","going"],"k":1,"e":"A plan → am going to.","h":"خطة going to."},{"n":8,"s":"______ you help me with my maths homework tonight?","o":["Are","Going","Do","Will"],"k":3,"e":"A request about the future → Will you …?","h":"طلب عن المستقبل Will."},{"n":9,"s":"Don't worry. The bus ______ soon.","o":["will come","comes soon will","will comes","coming"],"k":0,"e":"Prediction / reassurance → will + base verb.","h":"will مع الفعل الأصلي."},{"n":10,"s":"My uncle ______ from London at 10 p.m. tonight. We're meeting him at the airport.","o":["arrives at","will arriving","arrive","is arriving"],"k":3,"e":"An arranged event with a time → is arriving.","h":"ترتيب مؤكد."},{"n":11,"s":"I'm not sure, but I think it ______ cold in Abha tomorrow.","o":["is being","will","will be","be"],"k":2,"e":"Opinion prediction → will be.","h":"توقع مبني على الرأي."},{"n":12,"s":"She has saved a lot of money. She ______ buy a new laptop.","o":["will to","is going to","goes to","is going"],"k":1,"e":"Intention based on what she has done → is going to.","h":"نية مسبقة."},{"n":13,"s":"When you ______ in Riyadh, call me.","o":["will arrive","are going to arrive","arrive","arrived"],"k":2,"e":"After when (future) → present simple.","h":"بعد when المضارع البسيط."},{"n":14,"s":"\"The doorbell is ringing.\" \"Don't get up. I ______.\"","o":["'ll go","go","'m going to go","went"],"k":0,"e":"Instant decision → I'll go.","h":"قرار لحظي."},{"n":15,"s":"We ______ a party on Friday. Would you like to come?","o":["have","are having","will having","had"],"k":1,"e":"An arranged event → present continuous.","h":"ترتيب مؤكد."},{"n":16,"s":"I don't think the shops ______ open on Eid morning.","o":["are going be","be","will be","will"],"k":2,"e":"Opinion (I don't think) → will be.","h":"رأي عن المستقبل."},{"n":17,"s":"Be careful! You ______ hit your head on the door.","o":["will to","are going to","are hitting","hit"],"k":1,"e":"Evidence now → are going to.","h":"دليل حاضر."},{"n":18,"s":"As soon as the rain ______, we'll go out.","o":["will stop","stops","is going to stop","stopped"],"k":1,"e":"After as soon as → present simple.","h":"بعد as soon as المضارع."},{"n":19,"s":"\"Are you free tomorrow evening?\" \"No, I ______ my grandparents at seven.\"","o":["visit","will visiting","visited","'m visiting"],"k":3,"e":"An arranged visit with a time → present continuous.","h":"ترتيب محدد بوقت."},{"n":20,"s":"In the future, people probably ______ in smart cities like NEOM.","o":["will live","are living","live","going to live"],"k":0,"e":"A general prediction (probably) → will live.","h":"توقع عام will."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"I (A) will to send you (B) the photos (C) from the trip (D) tonight.","o":["will to send","the","from","tonight"],"k":0,"e":"No to after will.","h":""},{"n":22,"s":"My (A) brother (B) going to study (C) engineering (D) next year.","o":["brother","going to","engineering","next"],"k":1,"e":"be going to needs is.","h":""},{"n":23,"s":"We (A) will stay at home (B) tomorrow (C) if it (D) will rain.","o":["will","tomorrow","if","will rain"],"k":3,"e":"After if (future) → present simple rains.","h":""},{"n":24,"s":"Next (A) weekend she (B) will (C) visits her (D) aunt.","o":["weekend","will","visits","aunt"],"k":2,"e":"After will → base form visit.","h":""},{"n":25,"s":"(A) Look at those (B) dark clouds! It (C) will (D) rain soon.","o":["Look","dark","will","rain"],"k":2,"e":"Evidence (Look at those clouds) → is going to.","h":""},{"n":26,"s":"We (A) are (B) meet the new (C) teacher (D) at 9 tomorrow.","o":["are","meet","teacher","at"],"k":1,"e":"Present continuous needs -ing: meeting.","h":""},{"n":27,"s":"(A) Are you (B) going (C) to (D) came to the meeting on Monday?","o":["Are","going","to","came"],"k":3,"e":"going to + base form come.","h":""},{"n":28,"s":"I (A) won't (B) forget to (C) call you when I (D) will get home.","o":["won't","forget","call","will get"],"k":3,"e":"After when → present simple get.","h":""},{"n":29,"s":"(A) I am thinking the new mall (B) will (C) open (D) next year.","o":["I am thinking","will","open","next"],"k":0,"e":"think (= believe) is stative, so we use I think.","h":""},{"n":30,"s":"My (A) parents (B) are (C) going to (D) buying a new house.","o":["parents","are","going to","buying"],"k":3,"e":"going to + base form buy.","h":""}]}],"n":30},{"id":"2.4","t":"Comparatives, Superlatives and (not) as … as","html":"<p><strong>Unit 2 · Lesson 2.4 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Form comparatives and superlatives of short, long and irregular adjectives.</p>\n<p>2. Use than and the … in / of correctly.</p>\n<p>3. Express equality and difference with (not) as … as.</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يكوّن الطالب صيغ المقارنة والتفضيل للصفات القصيرة والطويلة والشاذة.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يستخدم than وthe … in/of استخدامًا صحيحًا.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يعبّر عن التساوي والاختلاف باستخدام as … as وnot as … as.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. Riyadh is ______ than Taif in summer.</strong></p>\n<blockquote>\n<p>A. hot B. hotter C. hottest D. more hot</p>\n</blockquote>\n<p><strong>2. This is the ______ book in the library.</strong></p>\n<blockquote>\n<p>A. oldest B. older C. old D. most old</p>\n</blockquote>\n<p><strong>3. My bag is as heavy ______ yours.</strong></p>\n<blockquote>\n<p>A. than B. like C. that D. as</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>Short adjectives (one syllable)</strong></p>\n<p><strong>adj + -er than · the + adj + -est</strong></p>\n<p><em>e.g. tall → taller → the tallest · cheap → cheaper → the cheapest</em></p>\n<p><strong>Spelling: -e / double / -y</strong></p>\n<p><strong>nice → nicer · big → bigger · hot → hotter · easy → easier → the easiest · busy → busier</strong></p>\n<p><em>e.g. Today is hotter than yesterday.</em></p>\n<p><strong>Long adjectives (two or more syllables)</strong></p>\n<p><strong>more + adj + than · the most + adj</strong></p>\n<p><em>e.g. expensive → more expensive → the most expensive</em></p>\n<p><strong>Irregular</strong></p>\n<p><strong>good → better → the best · bad → worse → the worst · far → farther / further → the farthest</strong></p>\n<p><em>e.g. Your idea is better than mine.</em></p>\n<p><strong>Less / least</strong></p>\n<p><strong>less + adj + than · the least + adj</strong></p>\n<p><em>e.g. This test was less difficult than the last one.</em></p>\n<p><strong>Equality</strong></p>\n<p><strong>as + adj + as · not as / so + adj + as</strong></p>\n<p><em>e.g. My brother is as tall as my father. The bus is not as fast as the metro.</em></p>\n<p><strong>Superlative + in / of</strong></p>\n<p><strong>the + superlative + in + place / group · of + number or period</strong></p>\n<p><em>e.g. the tallest building in the city · the best day of the year</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. Comparatives compare two things.</strong></p>\n<p>We use the comparative form + than.</p>\n<blockquote>\n<p>▸ Jeddah is more humid than Riyadh.</p>\n<p>▸ The metro is faster than the bus.</p>\n<p>▸ This phone is cheaper than that one.</p>\n</blockquote>\n<p><strong>2. Superlatives compare one thing with a whole group.</strong></p>\n<p>We use the + superlative, often with in or of.</p>\n<blockquote>\n<p>▸ The Kingdom Tower is one of the tallest buildings in the world.</p>\n<p>▸ Fahad is the youngest student in our class.</p>\n<p>▸ It was the best day of my holiday.</p>\n</blockquote>\n<p><strong>3. as … as shows things are equal; not as … as shows they are different.</strong></p>\n<p>The adjective in the middle is in its basic form.</p>\n<blockquote>\n<p>▸ Huda is as clever as her sister.</p>\n<p>▸ Taif isn't as hot as Riyadh in summer.</p>\n<p>▸ The second exam was not as easy as the first.</p>\n</blockquote>\n<p><strong>4. Making comparisons stronger or weaker.</strong></p>\n<p>much, far, a lot and a little can come before a comparative.</p>\n<blockquote>\n<p>▸ The new mall is much bigger than the old one.</p>\n<p>▸ My score was a little higher than yours.</p>\n<p>▸ The second road is far quieter than the first.</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ Two-syllable adjectives ending in -y take -er / -est: happy → happier → the happiest.</p>\n<p>▸ Never use more with -er: ✗ more taller ✓ taller.</p>\n<p>▸ After than and as, use an object pronoun in informal English (taller than me) or subject + verb (taller than I am).</p>\n<p>▸ the is needed before a superlative: She is the best (not She is best student).</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">عند المقارنة بين شيئين نضيف er إلى الصفة القصيرة ثم than، مثل taller than، ونستخدم more مع الصفة الطويلة، مثل more expensive than. ولا نجمع more وer معًا.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">عند التفضيل على مجموعة نستخدم the مع est للصفة القصيرة، أو the most للصفة الطويلة، ونستخدم in مع المكان أو المجموعة وof مع العدد أو الفترة.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">للتعبير عن التساوي نستخدم as + الصفة + as، وللنفي not as … as. وهناك صفات شاذة مثل good → better → the best وbad → worse → the worst.</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>more taller</em> <strong>→ ✓ taller</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا نجمع more مع er.</span></p>\n<p><strong>✗</strong> <em>He is taller from me.</em> <strong>→ ✓ He is taller than me.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">حرف المقارنة than وليس from.</span></p>\n<p><strong>✗</strong> <em>the most best</em> <strong>→ ✓ the best</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">best صيغة تفضيل كاملة.</span></p>\n<p><strong>✗</strong> <em>She is best student in class.</em> <strong>→ ✓ She is the best student in the class.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">نضع the قبل صيغة التفضيل.</span></p>\n<p><strong>✗</strong> <em>the biggest city of Saudi Arabia</em> <strong>→ ✓ the biggest city in Saudi Arabia</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">مع المكان نستخدم in.</span></p>\n<p><strong>✗</strong> <em>as tall than</em> <strong>→ ✓ as tall as</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">التساوي بـ as … as.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>Comparative (2 things): Ali is taller than Omar.</p>\n<p>Superlative (group): Ali is the tallest in the class.</p>\n<p>Equality: Ali is as tall as his father.</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. Look for than → comparative; look for the … in / of → superlative; look for as … as → basic adjective.</p>\n<p>2. Count syllables: short → -er / -est; long → more / most.</p>\n<p>3. Learn the irregular forms: better / best, worse / worst, farther / farthest.</p>\n<p>4. Reject double forms (more bigger, most fastest).</p>\n<p>5. STEP error items often put from instead of than, or of instead of in.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">ابحث عن than لاختيار المقارنة، وعن the … in/of لاختيار التفضيل، وعن as … as لاستخدام الصفة الأصلية، واحفظ الصيغ الشاذة.</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. This summer was ______ than last summer.</strong></p>\n<blockquote>\n<p>A. hottest B. more hot C. hotter D. the hotter</p>\n<p><strong>Step 1:</strong> than tells us we need a comparative.</p>\n<p><strong>Step 2:</strong> hot is short: hot → hotter (double t).</p>\n<p><strong>Step 3:</strong> The answer is C.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">مع than نحتاج صيغة المقارنة hotter.</span></p>\n<p><strong>Example 2. Mount Sawda is the ______ mountain in Saudi Arabia.</strong></p>\n<blockquote>\n<p>A. highest B. higher C. most high D. high</p>\n<p><strong>Step 1:</strong> the … in Saudi Arabia → superlative.</p>\n<p><strong>Step 2:</strong> high is short → the highest.</p>\n<p><strong>Step 3:</strong> The answer is A.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">the مع in تدل على التفضيل.</span></p>\n<p><strong>Example 3. My new (A) <u>phone</u> is (B) <u>more</u> (C) <u>faster</u> than my old (D) <u>one</u>.</strong></p>\n<blockquote>\n<p>A. phone B. more C. faster D. one</p>\n<p><strong>Step 1:</strong> We cannot use more and -er together.</p>\n<p><strong>Step 2:</strong> The correct form is faster (or remove more).</p>\n<p><strong>Step 3:</strong> Correct: My new phone is much faster than my old one. The answer is C.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا نجمع more مع er.</span></p>","wu":"Warm-up: 1 B · 2 A · 3 D · Worked examples: Example 1 C · Example 2 A · Example 3 C","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"A car is ______ than a bicycle.","o":["fast","faster","fastest","more fast"],"k":1,"e":"than → comparative; fast → faster.","h":"مع than صيغة المقارنة."},{"n":2,"s":"Nora is the ______ girl in her family.","o":["younger","young","youngest","most young"],"k":2,"e":"the … in her family → superlative.","h":"التفضيل مع the."},{"n":3,"s":"This dress is ______ than that one.","o":["expensiver","most expensive","the expensive","more expensive"],"k":3,"e":"Long adjective → more expensive than.","h":"الصفة الطويلة more."},{"n":4,"s":"My bag is as ______ as yours.","o":["bigger","biggest","big","the big"],"k":2,"e":"as … as uses the basic adjective.","h":"as … as مع الصفة الأصلية."},{"n":5,"s":"Today's test was ______ than yesterday's.","o":["easier","easyer","more easy","easiest"],"k":0,"e":"easy → easier (-y → -ier).","h":"y تصبح ier."},{"n":6,"s":"This is the ______ restaurant in our town.","o":["better","goodest","most good","best"],"k":3,"e":"good → the best.","h":"تفضيل good هو best."},{"n":7,"s":"The weather today is ______ than yesterday. It's raining all day.","o":["badder","worse","worst","more bad"],"k":1,"e":"bad → worse.","h":"مقارنة bad هي worse."},{"n":8,"s":"An elephant is ______ than a horse.","o":["heavier","heavyer","more heavy","heaviest"],"k":0,"e":"heavy → heavier.","h":"heavier."},{"n":9,"s":"Riyadh is the ______ city in Saudi Arabia.","o":["bigest","most big","bigger","biggest"],"k":3,"e":"big → the biggest (double g).","h":"نضاعف g."},{"n":10,"s":"My brother is taller ______ my father now.","o":["from","as","that","than"],"k":3,"e":"Comparatives use than.","h":"المقارنة بـ than."},{"n":11,"s":"The bus isn't as ______ as the metro.","o":["fast","faster","fastest","more fast"],"k":0,"e":"not as … as + basic adjective.","h":"الصفة الأصلية مع as."},{"n":12,"s":"This is the most ______ film I have ever seen.","o":["interested","interesting","interestinger","more interesting"],"k":1,"e":"the most + long adjective (interesting).","h":"the most مع الصفة الطويلة."},{"n":13,"s":"Khalid is the best player ______ the team.","o":["in","of","than","at"],"k":0,"e":"Superlative + in + group.","h":"مع المجموعة in."},{"n":14,"s":"The new library is much ______ than the old one.","o":["big","more big","biggest","bigger"],"k":3,"e":"much + comparative.","h":"much مع المقارنة."},{"n":15,"s":"It was the happiest day ______ my life.","o":["in","than","of","at"],"k":2,"e":"the … of my life (a period).","h":"مع الفترة of."},{"n":16,"s":"Gold is ______ than silver.","o":["valuabler","most valuable","more valuable","the more valuable"],"k":2,"e":"Long adjective → more valuable than.","h":"الصفة الطويلة."},{"n":17,"s":"Your English is getting ______. Well done!","o":["gooder","better","more good","best"],"k":1,"e":"good → better.","h":"مقارنة good هي better."},{"n":18,"s":"This chair is less ______ than the sofa.","o":["comfortable","comfortabler","more comfortable","most comfortable"],"k":0,"e":"less + basic adjective.","h":"less مع الصفة الأصلية."},{"n":19,"s":"Of the three brothers, Saud is the ______.","o":["taller","tallest","most tall","tall"],"k":1,"e":"Of three → superlative: the tallest.","h":"من ثلاثة نستخدم التفضيل."},{"n":20,"s":"The journey by car was not ______ long as we expected.","o":["so as","as","than","more"],"k":1,"e":"not as … as.","h":"not as … as."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"This exam (A) was (B) more difficult (C) from the last (D) one.","o":["was","more difficult","from","one"],"k":2,"e":"Comparatives use than, not from.","h":""},{"n":22,"s":"(A) The more tall building in Jeddah (B) is (C) near (D) the sea.","o":["The more tall","is","near","the"],"k":0,"e":"Superlative of tall → the tallest.","h":""},{"n":23,"s":"My father's car is (A) older (B) than my uncle's, but it is (C) as fast (D) than his.","o":["older","than","as","than"],"k":3,"e":"Equality uses as … as.","h":""},{"n":24,"s":"Today is (A) the (B) most hot day (C) of the (D) year.","o":["the","most hot","of","year"],"k":1,"e":"hot is short → the hottest.","h":""},{"n":25,"s":"This book is (A) more better (B) than the (C) one I read (D) last week.","o":["more better","than","one","last"],"k":0,"e":"better is already comparative; remove more.","h":""},{"n":26,"s":"Sara is (A) the (B) youngest (C) from all her (D) sisters.","o":["the","youngest","from","sisters"],"k":2,"e":"Superlative + of + a group of people: of all her sisters.","h":""},{"n":27,"s":"Mount Everest is (A) the (B) highest mountain (C) in (D) a world.","o":["the","highest","in","a"],"k":3,"e":"There is only one world → the world.","h":""},{"n":28,"s":"This road is (A) not (B) as busier as (C) the (D) highway.","o":["not","as busier","the","highway"],"k":1,"e":"as … as uses the basic adjective busy.","h":""},{"n":29,"s":"My grandmother is (A) the (B) kindest (C) persons (D) in our family.","o":["the","kindest","persons","in"],"k":2,"e":"After the kindest we need the singular person.","h":""},{"n":30,"s":"(A) Faisal is tallest than (B) his brother, but (C) shorter than (D) his father.","o":["Faisal is tallest","his","shorter","his"],"k":0,"e":"than needs the comparative taller.","h":""}]}],"n":30},{"id":"2.5","t":"Present Perfect: ever, never, just, already, yet","html":"<p><strong>Unit 2 · Lesson 2.5 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Form the present perfect with have / has + past participle.</p>\n<p>2. Talk about life experience with ever and never.</p>\n<p>3. Place just, already and yet correctly in positive, negative and question sentences.</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يكوّن الطالب المضارع التام بصيغة have/has مع التصريف الثالث.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يتحدث عن التجارب الحياتية باستخدام ever وnever.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يضع just وalready وyet في مواضعها الصحيحة في الإثبات والنفي والسؤال.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. I have ______ my homework.</strong></p>\n<blockquote>\n<p>A. finish B. finishing C. finishes D. finished</p>\n</blockquote>\n<p><strong>2. ______ you ever been to Abha?</strong></p>\n<blockquote>\n<p>A. Have B. Did C. Are D. Has</p>\n</blockquote>\n<p><strong>3. She hasn't called me ______.</strong></p>\n<blockquote>\n<p>A. already B. just C. yet D. ever</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>Positive</strong></p>\n<p><strong>I / you / we / they + have ('ve) + past participle · he / she / it + has ('s) + past participle</strong></p>\n<p><em>e.g. I have visited AlUla. She has finished.</em></p>\n<p><strong>Negative</strong></p>\n<p><strong>haven't / hasn't + past participle</strong></p>\n<p><em>e.g. We haven't eaten. He hasn't called.</em></p>\n<p><strong>Questions and short answers</strong></p>\n<p><strong>Have / Has + subject + past participle …? — Yes, I have. / No, she hasn't.</strong></p>\n<p><em>e.g. Have you seen this film? No, I haven't.</em></p>\n<p><strong>Past participles</strong></p>\n<p><strong>regular = -ed (visited) · irregular: be → been, go → gone, see → seen, eat → eaten, write → written, do → done</strong></p>\n<p><em>e.g. Have you ever eaten camel meat?</em></p>\n<p><strong>ever / never (experience)</strong></p>\n<p><strong>Have you ever + p.p. …? · I have never + p.p.</strong></p>\n<p><em>e.g. I have never flown in a helicopter.</em></p>\n<p><strong>just / already (before the participle)</strong></p>\n<p><strong>have just + p.p. · have already + p.p.</strong></p>\n<p><em>e.g. The bus has just left. I've already paid.</em></p>\n<p><strong>yet (end of negatives and questions)</strong></p>\n<p><strong>haven't + p.p. … yet · Have … p.p. … yet?</strong></p>\n<p><em>e.g. Has the film started yet? It hasn't started yet.</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. Life experience (at any time until now).</strong></p>\n<p>We use the present perfect with ever and never when the time is not important.</p>\n<blockquote>\n<p>▸ Have you ever visited the Red Sea Project?</p>\n<p>▸ My grandmother has never used a laptop.</p>\n<p>▸ I have read this book three times.</p>\n</blockquote>\n<p><strong>2. just = a very short time ago.</strong></p>\n<p>just shows that something happened a moment ago.</p>\n<blockquote>\n<p>▸ I've just finished my lunch.</p>\n<p>▸ The teacher has just arrived.</p>\n<p>▸ Has the match just started?</p>\n</blockquote>\n<p><strong>3. already = sooner than expected.</strong></p>\n<p>already shows that something has happened, maybe earlier than people think.</p>\n<blockquote>\n<p>▸ \"Do your homework.\" \"I've already done it!\"</p>\n<p>▸ They have already booked the hotel.</p>\n<p>▸ The guests have already arrived.</p>\n</blockquote>\n<p><strong>4. yet = up to now (in negatives and questions).</strong></p>\n<p>yet goes at the end of the sentence.</p>\n<blockquote>\n<p>▸ Have you finished your project yet?</p>\n<p>▸ My cousin hasn't replied to my message yet.</p>\n<p>▸ The results haven't come out yet.</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ Do NOT use the present perfect with a finished time (yesterday, last week, in 2020): ✗ I have seen him yesterday.</p>\n<p>▸ been vs gone: He has gone to Jeddah (he is there now). He has been to Jeddah (he went and came back).</p>\n<p>▸ never already has a negative meaning: ✗ I haven't never …</p>\n<p>▸ ever is mainly for questions: Have you ever …?</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">المضارع التام يتكون من have أو has مع التصريف الثالث للفعل، ونستخدمه للحديث عن تجارب حدثت في أي وقت حتى الآن دون تحديد زمنها، مثل Have you ever visited Abha?</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">تأتي just وalready بين have والتصريف الثالث؛ just تعني «للتو»، وalready تعني «بالفعل أو سابقًا». أما yet فتأتي في نهاية الجملة المنفية أو السؤال وتعني «حتى الآن».</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا نستخدم المضارع التام مع زمن ماضٍ محدد مثل yesterday وlast week، بل نستخدم الماضي البسيط.</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>I have saw this film.</em> <strong>→ ✓ I have seen this film.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد have نستخدم التصريف الثالث seen.</span></p>\n<p><strong>✗</strong> <em>She have finished.</em> <strong>→ ✓ She has finished.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">she تأخذ has.</span></p>\n<p><strong>✗</strong> <em>I have visited Taif last week.</em> <strong>→ ✓ I visited Taif last week.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">مع زمن ماضٍ محدد نستخدم الماضي البسيط.</span></p>\n<p><strong>✗</strong> <em>I didn't finish yet.</em> <strong>→ ✓ I haven't finished yet.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">yet تأتي مع المضارع التام غالبًا.</span></p>\n<p><strong>✗</strong> <em>I have finished just.</em> <strong>→ ✓ I have just finished.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">just تأتي قبل التصريف الثالث.</span></p>\n<p><strong>✗</strong> <em>I haven't never been there.</em> <strong>→ ✓ I have never been there.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">never تحمل معنى النفي.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>Past simple (finished time): I visited Abha in 2022.</p>\n<p>Present perfect (no time / until now): I have visited Abha twice.</p>\n<p>just / already (middle) · yet (end)</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. have / has + past participle — check BOTH parts.</p>\n<p>2. If the sentence has a finished time (yesterday, ago, last), choose the past simple, not the present perfect.</p>\n<p>3. just and already go between have and the participle; yet goes at the end.</p>\n<p>4. ever → questions; never → positive verb with negative meaning.</p>\n<p>5. Learn irregular participles (gone, seen, eaten, written) — Appendix A, column 3.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">تأكد من وجود have أو has مع التصريف الثالث، واختر الماضي البسيط إذا وُجد زمن ماضٍ محدد، وضع just وalready في الوسط وyet في النهاية.</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. \"Is Majed here?\" \"No, he has ______ left. You missed him by a minute.\"</strong></p>\n<blockquote>\n<p>A. yet B. ever C. just D. never</p>\n<p><strong>Step 1:</strong> You missed him by a minute → a very short time ago.</p>\n<p><strong>Step 2:</strong> A very short time ago → just.</p>\n<p><strong>Step 3:</strong> The answer is C.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">حدث للتو فنستخدم just.</span></p>\n<p><strong>Example 2. Have you ______ eaten Japanese food?</strong></p>\n<blockquote>\n<p>A. ever B. yet C. already D. never</p>\n<p><strong>Step 1:</strong> The question asks about life experience.</p>\n<p><strong>Step 2:</strong> Experience questions use ever.</p>\n<p><strong>Step 3:</strong> The answer is A.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">السؤال عن التجربة يكون بـ ever.</span></p>\n<p><strong>Example 3. My (A) <u>father</u> has (B) <u>went</u> to the (C) <u>bank</u>, but he will be (D) <u>back</u> soon.</strong></p>\n<blockquote>\n<p>A. father B. went C. bank D. back</p>\n<p><strong>Step 1:</strong> has needs a past participle.</p>\n<p><strong>Step 2:</strong> The past participle of go is gone.</p>\n<p><strong>Step 3:</strong> Correct: My father has gone to the bank, but he will be back soon. The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد has التصريف الثالث gone.</span></p>","wu":"Warm-up: 1 D · 2 A · 3 C · Worked examples: Example 1 C · Example 2 A · Example 3 B","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"I have ______ my keys. I can't find them anywhere.","o":["lose","losing","lost","loses"],"k":2,"e":"have + past participle lost.","h":"بعد have التصريف الثالث."},{"n":2,"s":"She ______ visited many countries in Asia.","o":["have","is","has","did"],"k":2,"e":"she → has + past participle.","h":"she تأخذ has."},{"n":3,"s":"______ you ever ridden a horse?","o":["Did","Have","Has","Are"],"k":1,"e":"Experience question → Have you ever …?","h":"سؤال التجربة Have."},{"n":4,"s":"We have ______ finished our lunch. It was delicious.","o":["yet","ever","since","just"],"k":3,"e":"A moment ago → just (before the participle).","h":"just قبل التصريف الثالث."},{"n":5,"s":"They haven't arrived ______.","o":["already","just","ever","yet"],"k":3,"e":"Negative + end position → yet.","h":"yet في نهاية النفي."},{"n":6,"s":"I have ______ been to Japan, but I'd like to go.","o":["never","ever","yet","already"],"k":0,"e":"No experience → never.","h":"never لعدم التجربة."},{"n":7,"s":"My brother has ______ three books this month.","o":["wrote","writed","written","write"],"k":2,"e":"write → written (participle).","h":"التصريف الثالث written."},{"n":8,"s":"\"Has the film started?\" \"Yes, it ______.\"","o":["have","has","did","is"],"k":1,"e":"Short answer: Yes, it has.","h":"الإجابة القصيرة Yes, it has."},{"n":9,"s":"I have ______ done my homework, so I can watch TV now.","o":["yet","ever","already","never"],"k":2,"e":"Sooner than expected → already.","h":"already بمعنى بالفعل."},{"n":10,"s":"Have you seen the new museum ______?","o":["yet","already","just","never"],"k":0,"e":"Question + end position → yet.","h":"yet في نهاية السؤال."},{"n":11,"s":"Sami ______ his phone yesterday.","o":["has broken","have broken","broken","broke"],"k":3,"e":"yesterday is finished time → past simple broke.","h":"مع yesterday الماضي البسيط."},{"n":12,"s":"My parents have ______ to Makkah. They will come back next week.","o":["been","go","gone","went"],"k":2,"e":"They are there now → gone.","h":"gone لأنهم ما زالوا هناك."},{"n":13,"s":"I have ______ this film twice. It's great!","o":["saw","seen","see","seeing"],"k":1,"e":"see → seen.","h":"التصريف الثالث seen."},{"n":14,"s":"\"Have you eaten?\" \"No, I ______. I'm hungry.\"","o":["didn't","don't","haven't","hasn't"],"k":2,"e":"Short answer: No, I haven't.","h":"الإجابة القصيرة No, I haven't."},{"n":15,"s":"Hessa has ______ to Paris twice, so she knows the city well.","o":["gone","been","go","went"],"k":1,"e":"She went and came back → been.","h":"been لأنها عادت."},{"n":16,"s":"The plane ______ just landed at King Khalid Airport.","o":["have","is","did","has"],"k":3,"e":"The plane → has just + participle.","h":"الفاعل مفرد."},{"n":17,"s":"We ______ the hotel two weeks ago.","o":["booked","have booked","has booked","book"],"k":0,"e":"two weeks ago is finished time → past simple.","h":"ago مع الماضي البسيط."},{"n":18,"s":"Has your sister ______ her driving test yet?","o":["pass","passing","passes","passed"],"k":3,"e":"Has + past participle passed.","h":"بعد Has التصريف الثالث."},{"n":19,"s":"I've ______ tried this restaurant. Is it good?","o":["ever","yet","never","already"],"k":2,"e":"No experience + question about quality → never.","h":"لم يجرب المطعم."},{"n":20,"s":"\"Shall I buy some bread?\" \"No, thanks. Dad has ______ bought some.\"","o":["already","yet","ever","still"],"k":0,"e":"It happened earlier than expected → already.","h":"already."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"I (A) have (B) saw that film, but I (C) don't remember (D) it.","o":["have","saw","don't","it"],"k":1,"e":"have + past participle seen.","h":""},{"n":22,"s":"(A) Have you (B) finished your project? No, I (C) haven't finished it (D) already.","o":["Have","finished","haven't","already"],"k":3,"e":"In negatives we use yet, not already.","h":""},{"n":23,"s":"My (A) uncle and (B) aunt (C) has (D) lived in Taif for many years.","o":["uncle","aunt","has","lived"],"k":2,"e":"My uncle and aunt is plural → have.","h":""},{"n":24,"s":"We (A) have (B) visited the (C) museum (D) last Saturday.","o":["have","visited","museum","last"],"k":0,"e":"last Saturday is finished time → past simple (remove have).","h":""},{"n":25,"s":"I (A) have (B) finished just (C) my (D) homework.","o":["have","finished just","my","homework"],"k":1,"e":"just goes before the participle.","h":""},{"n":26,"s":"She (A) hasn't never been (B) on a (C) plane (D) before.","o":["hasn't never","on","plane","before"],"k":0,"e":"never already makes the sentence negative.","h":""},{"n":27,"s":"(A) Has the (B) teacher (C) checked our tests (D) still?","o":["Has","teacher","checked","still"],"k":3,"e":"Questions about until now use yet.","h":""},{"n":28,"s":"They have (A) already (B) finished the dates, and they (C) have (D) ate the biscuits too.","o":["already","finished","have","ate"],"k":3,"e":"eat → eaten (participle).","h":""},{"n":29,"s":"(A) Did you ever (B) been to Al-Ahsa? It (C) is a (D) beautiful oasis.","o":["Did","been","is","beautiful"],"k":0,"e":"Experience question → Have you ever been …?","h":""},{"n":30,"s":"My (A) friends have (B) gone to Riyadh (C) twice and came (D) back happy.","o":["friends","gone","twice","back"],"k":1,"e":"They came back → been, not gone.","h":""}]}],"n":30},{"id":"2.6","t":"Obligation and Advice: must, have to, should, mustn't, don't have to","html":"<p><strong>Unit 2 · Lesson 2.6 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Use must and have to for obligation.</p>\n<p>2. Tell mustn't (prohibition) from don't have to (no necessity).</p>\n<p>3. Give advice with should / shouldn't + base form.</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يستخدم الطالب must وhave to للتعبير عن الإلزام.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يميّز بين mustn't (المنع) وdon't have to (عدم الضرورة).</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يقدّم النصيحة باستخدام should وshouldn't مع الفعل الأصلي.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. You ______ wear a seatbelt in the car. It's the law.</strong></p>\n<blockquote>\n<p>A. must B. mustn't C. don't have to D. shouldn't</p>\n</blockquote>\n<p><strong>2. You look tired. You ______ go to bed early.</strong></p>\n<blockquote>\n<p>A. mustn't B. should C. don't have to D. has to</p>\n</blockquote>\n<p><strong>3. It's Friday. We ______ go to school today.</strong></p>\n<blockquote>\n<p>A. mustn't B. must C. don't have to D. should</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>must / mustn't</strong></p>\n<p><strong>Subject + must / mustn't + base verb (same for all subjects)</strong></p>\n<p><em>e.g. You must listen. Students mustn't use phones in exams.</em></p>\n<p><strong>have to / has to</strong></p>\n<p><strong>I / you / we / they + have to + base verb · he / she / it + has to + base verb</strong></p>\n<p><em>e.g. I have to wake up at six. She has to wear a uniform.</em></p>\n<p><strong>don't / doesn't have to</strong></p>\n<p><strong>Subject + don't / doesn't have to + base verb</strong></p>\n<p><em>e.g. We don't have to pay. He doesn't have to come.</em></p>\n<p><strong>have to — questions</strong></p>\n<p><strong>Do / Does + subject + have to + base verb …?</strong></p>\n<p><em>e.g. Do you have to work on Saturday?</em></p>\n<p><strong>Past obligation</strong></p>\n<p><strong>had to + base verb (must has no past form)</strong></p>\n<p><em>e.g. I had to stay at home yesterday.</em></p>\n<p><strong>should / shouldn't</strong></p>\n<p><strong>Subject + should / shouldn't + base verb</strong></p>\n<p><em>e.g. You should drink more water. You shouldn't eat late.</em></p>\n<p><strong>should — questions</strong></p>\n<p><strong>Should + subject + base verb …?</strong></p>\n<p><em>e.g. Should I take an umbrella?</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. must and have to: obligation.</strong></p>\n<p>must often shows the speaker's feeling or a written rule; have to shows an outside rule or necessity.</p>\n<blockquote>\n<p>▸ I must call my grandmother tonight. (I feel it is important.)</p>\n<p>▸ Drivers must stop at a red light.</p>\n<p>▸ My brother has to wear a uniform at work.</p>\n</blockquote>\n<p><strong>2. mustn't: prohibition (it is not allowed).</strong></p>\n<p>mustn't means do not do it.</p>\n<blockquote>\n<p>▸ You mustn't touch the wires. They're dangerous.</p>\n<p>▸ Visitors mustn't feed the animals.</p>\n<p>▸ We mustn't be late for the exam.</p>\n</blockquote>\n<p><strong>3. don't have to: no necessity (you can choose).</strong></p>\n<p>don't have to means it is not necessary, but it is allowed.</p>\n<blockquote>\n<p>▸ You don't have to bring food. We'll buy lunch there.</p>\n<p>▸ Tomorrow is a holiday, so I don't have to wake up early.</p>\n<p>▸ She doesn't have to wear glasses for reading.</p>\n</blockquote>\n<p><strong>4. should / shouldn't: advice.</strong></p>\n<p>We use should to say what is a good idea.</p>\n<blockquote>\n<p>▸ You should revise every day before the exam.</p>\n<p>▸ You shouldn't drink so much coffee.</p>\n<p>▸ What should I buy for my mother's birthday?</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ must has no -s and no to: She must go. (not She musts go / must to go)</p>\n<p>▸ has to with he / she / it: He has to study. (not He have to)</p>\n<p>▸ The past of must and have to is had to.</p>\n<p>▸ Big difference: You mustn't go (it's forbidden) ≠ You don't have to go (it's your choice).</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">نستخدم must وhave to للتعبير عن الإلزام؛ و must غالبًا تعبّر عن رأي المتكلم أو القوانين المكتوبة، بينما have to تعبّر عن ضرورة خارجية. ويأتي بعدهما الفعل في صورته الأصلية، ونقول has to مع he وshe وit.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الفرق مهم جدًا بين mustn't ومعناها «ممنوع»، وdon't have to ومعناها «ليس ضروريًا»، فالأولى منع والثانية حرية اختيار.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">نستخدم should للنصيحة وshouldn't للنصيحة بعدم فعل شيء، والماضي من must وhave to هو had to.</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>You must to wear a helmet.</em> <strong>→ ✓ You must wear a helmet.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا نضع to بعد must.</span></p>\n<p><strong>✗</strong> <em>He have to work late.</em> <strong>→ ✓ He has to work late.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">he تأخذ has to.</span></p>\n<p><strong>✗</strong> <em>You mustn't come tomorrow; it's optional.</em> <strong>→ ✓ You don't have to come tomorrow.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">عدم الضرورة = don't have to، أما mustn't فمنع.</span></p>\n<p><strong>✗</strong> <em>I must went yesterday.</em> <strong>→ ✓ I had to go yesterday.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الماضي من must هو had to.</span></p>\n<p><strong>✗</strong> <em>You should to see a doctor.</em> <strong>→ ✓ You should see a doctor.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا to بعد should.</span></p>\n<p><strong>✗</strong> <em>She musts study.</em> <strong>→ ✓ She must study.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">must لا تأخذ s.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>mustn't = It is not allowed: You mustn't smoke here.</p>\n<p>don't have to = It is not necessary: You don't have to come early.</p>\n<p>should = It is a good idea: You should come early to get a good seat.</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. Decide the meaning first: rule / necessity (must, have to), forbidden (mustn't), not necessary (don't have to), advice (should).</p>\n<p>2. Check the verb after a modal: base form, no to (except have to / ought to).</p>\n<p>3. has to with he / she / it; had to for the past.</p>\n<p>4. Look for clues: It's the law / It's forbidden / It's optional / It's a good idea.</p>\n<p>5. STEP loves the mustn't vs don't have to contrast.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">حدّد المعنى أولًا: إلزام أم منع أم عدم ضرورة أم نصيحة، ثم تأكد أن الفعل بعد الفعل الناقص في صورته الأصلية دون to، وتذكّر أن الماضي هو had to.</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. The museum is free. You ______ pay for a ticket.</strong></p>\n<blockquote>\n<p>A. mustn't B. must C. should D. don't have to</p>\n<p><strong>Step 1:</strong> The museum is free → paying is not necessary.</p>\n<p><strong>Step 2:</strong> Not necessary → don't have to.</p>\n<p><strong>Step 3:</strong> The answer is D.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الدخول مجاني فالدفع ليس ضروريًا: don't have to.</span></p>\n<p><strong>Example 2. My cousin ______ go to the hospital yesterday because he broke his arm.</strong></p>\n<blockquote>\n<p>A. must B. had to C. has to D. should</p>\n<p><strong>Step 1:</strong> yesterday → past.</p>\n<p><strong>Step 2:</strong> The past of must / have to is had to.</p>\n<p><strong>Step 3:</strong> The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الماضي من must هو had to.</span></p>\n<p><strong>Example 3. (A) <u>Students</u> (B) <u>must to</u> switch (C) <u>off</u> their phones (D) <u>during</u> the test.</strong></p>\n<blockquote>\n<p>A. Students B. must to C. off D. during</p>\n<p><strong>Step 1:</strong> must is followed by the base form without to.</p>\n<p><strong>Step 2:</strong> must to switch → must switch.</p>\n<p><strong>Step 3:</strong> Correct: Students must switch off their phones during the test. The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا to بعد must.</span></p>","wu":"Warm-up: 1 A · 2 B · 3 C · Worked examples: Example 1 D · Example 2 B · Example 3 B","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"You ______ stop when the traffic light is red.","o":["mustn't","don't have to","shouldn't","must"],"k":3,"e":"A traffic rule → must.","h":"قاعدة مرورية must."},{"n":2,"s":"My sister ______ get up at 5:30 for work.","o":["have to","must to","has to","having to"],"k":2,"e":"My sister → has to.","h":"she تأخذ has to."},{"n":3,"s":"You look ill. You ______ see a doctor.","o":["mustn't","don't have to","should to","should"],"k":3,"e":"Advice → should + base verb.","h":"النصيحة should."},{"n":4,"s":"You ______ swim here. The water is dangerous.","o":["mustn't","don't have to","must","should"],"k":0,"e":"It's dangerous → it's forbidden: mustn't.","h":"ممنوع mustn't."},{"n":5,"s":"Tomorrow is Saturday, so I ______ go to school.","o":["mustn't","must","don't have to","has to"],"k":2,"e":"No school on Saturday → not necessary.","h":"ليس ضروريًا don't have to."},{"n":6,"s":"We ______ wear a uniform at our school. It's a rule.","o":["has to","have to","must to","should to"],"k":1,"e":"we → have to (rule).","h":"we تأخذ have to."},{"n":7,"s":"______ I take a jacket? Is it cold outside?","o":["Must to","Have","Do should","Should"],"k":3,"e":"Asking for advice → Should I …?","h":"طلب النصيحة Should I."},{"n":8,"s":"You ______ eat so many sweets. They're bad for your teeth.","o":["don't have to","mustn't to","shouldn't","should"],"k":2,"e":"Advice not to do something → shouldn't.","h":"نصيحة بالامتناع shouldn't."},{"n":9,"s":"Last week I ______ stay at home because I was sick.","o":["had to","must","have to","musted"],"k":0,"e":"Past obligation → had to.","h":"الماضي had to."},{"n":10,"s":"Passengers ______ use their phones during take-off.","o":["don't have to","doesn't have to","mustn't","must"],"k":2,"e":"Not allowed → mustn't.","h":"ممنوع."},{"n":11,"s":"You ______ bring a gift to the party, but you can if you want.","o":["mustn't","must","should to","don't have to"],"k":3,"e":"It's your choice → don't have to.","h":"اختياري."},{"n":12,"s":"______ your brother have to work on Fridays?","o":["Do","Does","Has","Is"],"k":1,"e":"Question with has to → Does … have to?","h":"السؤال Does … have to."},{"n":13,"s":"Visitors ______ take photos inside the gallery. It's not allowed.","o":["don't have to","mustn't","shouldn't to","can"],"k":1,"e":"not allowed → mustn't.","h":"ممنوع mustn't."},{"n":14,"s":"He doesn't ______ cook tonight. His mother is cooking.","o":["has to","must","had to","have to"],"k":3,"e":"doesn't + have to (base form).","h":"بعد doesn't نستخدم have to."},{"n":15,"s":"I think you ______ apologize to your friend.","o":["must to","should","have","should to"],"k":1,"e":"Opinion / advice → should + base verb.","h":"النصيحة should."},{"n":16,"s":"Did you ______ wait long at the airport?","o":["have to","had to","must","has to"],"k":0,"e":"Did + have to (base).","h":"بعد Did نستخدم have to."},{"n":17,"s":"Children under twelve ______ travel alone on this airline.","o":["mustn't","don't have to","doesn't have to","should"],"k":0,"e":"A rule that forbids → mustn't.","h":"قاعدة منع."},{"n":18,"s":"You ______ be rich to be happy.","o":["mustn't","must","have to","don't have to"],"k":3,"e":"Being rich is not necessary for happiness.","h":"ليس شرطًا."},{"n":19,"s":"My father says I ______ finish my homework before I play.","o":["mustn't","musts","must","must to"],"k":2,"e":"An obligation from the speaker → must + base verb.","h":"إلزام must."},{"n":20,"s":"Ali's new job is very easy. He ______ work hard.","o":["mustn't","don't have to","hasn't to","doesn't have to"],"k":3,"e":"Not necessary, with he → doesn't have to.","h":"ليس ضروريًا مع he."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"You (A) must (B) to wear a helmet when you (C) ride a (D) bike.","o":["must","to wear","ride","bike"],"k":1,"e":"No to after must.","h":""},{"n":22,"s":"My (A) father (B) have to (C) travel to Riyadh (D) every week.","o":["father","have to","travel","every"],"k":1,"e":"My father → has to.","h":""},{"n":23,"s":"You (A) mustn't (B) come early tomorrow; it's (C) your (D) choice.","o":["mustn't","come","your","choice"],"k":0,"e":"A choice = not necessary → don't have to.","h":""},{"n":24,"s":"(A) You (B) should (C) to drink more (D) water in summer.","o":["You","should","to drink","water"],"k":2,"e":"No to after should.","h":""},{"n":25,"s":"We (A) must (B) leave early (C) yesterday because of (D) the traffic.","o":["must","leave","yesterday","the"],"k":0,"e":"Past obligation → had to.","h":""},{"n":26,"s":"(A) Do I (B) should (C) bring my passport (D) to the bank?","o":["Do","should","bring","to"],"k":0,"e":"Questions with should start with Should, not Do.","h":""},{"n":27,"s":"She (A) doesn't (B) has to (C) pay for the (D) bus; it's free.","o":["doesn't","has to","pay","bus"],"k":1,"e":"After doesn't → have to.","h":""},{"n":28,"s":"Drivers (A) don't have to use (B) their phones (C) while they (D) are driving.","o":["don't have to","their","while","are"],"k":0,"e":"It is forbidden → mustn't.","h":""},{"n":29,"s":"The (A) doctor said that my (B) grandfather (C) musts (D) rest.","o":["doctor","grandfather","musts","rest"],"k":2,"e":"must never takes -s.","h":""},{"n":30,"s":"(A) Does your sister (B) have to (C) wears a uniform (D) at work?","o":["Does","have","wears","at"],"k":2,"e":"have to + base form wear.","h":""}]}],"n":30},{"id":"2.7","t":"Quantifiers and Articles","html":"<p><strong>Unit 2 · Lesson 2.7 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Choose some / any, much / many, a few / a little and a lot of with the right nouns.</p>\n<p>2. Use a / an, the and zero article in common patterns.</p>\n<p>3. Avoid using the with general plural and uncountable nouns (Water is important for life).</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يختار الطالب some وany وmuch وmany وa few وa little وa lot of مع الأسماء المناسبة.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يستخدم a وan وthe وغياب الأداة في الأنماط الشائعة.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يتجنب استخدام the مع الأسماء العامة الجمع وغير المعدودة.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. How ______ sugar do you want in your tea?</strong></p>\n<blockquote>\n<p>A. many B. much C. few D. a few</p>\n</blockquote>\n<p><strong>2. There are ______ apples in the basket.</strong></p>\n<blockquote>\n<p>A. a little B. much C. any D. some</p>\n</blockquote>\n<p><strong>3. ______ honey is good for your health.</strong></p>\n<blockquote>\n<p>A. The B. — C. A D. An</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>some / any</strong></p>\n<p><strong>some + plural / uncountable (positive, offers) · any + plural / uncountable (negative, questions)</strong></p>\n<p><em>e.g. I've got some dates. Have you got any milk? There aren't any chairs.</em></p>\n<p><strong>much / many</strong></p>\n<p><strong>many + plural countable · much + uncountable (mainly negative / questions)</strong></p>\n<p><em>e.g. How many brothers have you got? We don't have much time.</em></p>\n<p><strong>a lot of / lots of</strong></p>\n<p><strong>a lot of + plural or uncountable (all sentence types)</strong></p>\n<p><em>e.g. There are a lot of cars. She drinks a lot of water.</em></p>\n<p><strong>a few / a little</strong></p>\n<p><strong>a few + plural countable · a little + uncountable (= some, not many / much)</strong></p>\n<p><em>e.g. I have a few friends in Jeddah. Add a little salt.</em></p>\n<p><strong>a / an</strong></p>\n<p><strong>first mention · one of many · jobs · a + consonant sound / an + vowel sound</strong></p>\n<p><em>e.g. I saw a falcon. My aunt is a nurse.</em></p>\n<p><strong>the</strong></p>\n<p><strong>second mention · only one (the sun) · both speakers know it · superlatives · rivers, seas, deserts</strong></p>\n<p><em>e.g. The falcon was beautiful. the Red Sea · the Empty Quarter</em></p>\n<p><strong>Zero article (no article)</strong></p>\n<p><strong>general plural / uncountable nouns · meals · most countries and cities · sports · school subjects · at home / at school</strong></p>\n<p><em>e.g. Camels live in deserts. We have lunch at two. I love football.</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. some / any.</strong></p>\n<p>some is for positive sentences and offers; any is for negatives and most questions.</p>\n<blockquote>\n<p>▸ There is some juice in the fridge.</p>\n<p>▸ Would you like some coffee?</p>\n<p>▸ We didn't buy any bread.</p>\n<p>▸ Are there any questions?</p>\n</blockquote>\n<p><strong>2. much / many / a lot of.</strong></p>\n<p>many + plural, much + uncountable; a lot of works with both.</p>\n<blockquote>\n<p>▸ How many students are in your class?</p>\n<p>▸ I don't have much money with me.</p>\n<p>▸ There are a lot of tourists in AlUla in winter.</p>\n</blockquote>\n<p><strong>3. a few / a little.</strong></p>\n<p>They mean a small amount, but enough.</p>\n<blockquote>\n<p>▸ Wait a few minutes, please.</p>\n<p>▸ Can I have a little milk in my tea?</p>\n<p>▸ We met a few friends at the mall.</p>\n</blockquote>\n<p><strong>4. a / an vs the vs no article.</strong></p>\n<p>a / an for one non-specific thing; the for a specific or unique thing; no article for things in general.</p>\n<blockquote>\n<p>▸ I bought a book. The book is about space.</p>\n<p>▸ The moon is very bright tonight.</p>\n<p>▸ Doctors work very hard.</p>\n<p>▸ Rice is popular in Saudi Arabia.</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ Use the with: the sun, the moon, the world, the internet, the Red Sea, the Arabian Gulf, the Netherlands.</p>\n<p>▸ No article with: most cities and countries (Riyadh, Egypt), meals (have breakfast), sports, subjects, languages.</p>\n<p>▸ much is uncommon in positive sentences: ✓ a lot of time (not much time) in positive statements.</p>\n<p>▸ few / little (without a) = not enough: I have few friends here. (negative feeling)</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">نستخدم some في الجمل المثبتة والعروض، وany في النفي ومعظم الأسئلة، ونستخدم many مع الأسماء المعدودة الجمع، وmuch مع غير المعدودة، أما a lot of فتصلح للنوعين.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">a few تعني «عدد قليل» وتأتي مع المعدود، وa little تعني «كمية قليلة» وتأتي مع غير المعدود.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">في العربية نقول «الماء مهم للحياة» بأداة التعريف، أما في الإنجليزية فلا نستخدم the مع الأسماء العامة، فنقول Water is important for life. ونستخدم the مع الشيء المحدد أو الوحيد مثل the sun والبحار والصحارى.</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>The water is important for life.</em> <strong>→ ✓ Water is important for life.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الاسم العام لا يأخذ the في الإنجليزية.</span></p>\n<p><strong>✗</strong> <em>How much brothers do you have?</em> <strong>→ ✓ How many brothers do you have?</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">brothers معدودة فنستخدم many.</span></p>\n<p><strong>✗</strong> <em>I don't have some money.</em> <strong>→ ✓ I don't have any money.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">في النفي نستخدم any.</span></p>\n<p><strong>✗</strong> <em>a few water</em> <strong>→ ✓ a little water</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">water غير معدودة فنستخدم a little.</span></p>\n<p><strong>✗</strong> <em>I go to the school by bus.</em> <strong>→ ✓ I go to school by bus.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">نقول go to school دون the عند الحديث عن الدراسة.</span></p>\n<p><strong>✗</strong> <em>He plays the football.</em> <strong>→ ✓ He plays football.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الرياضات لا تأخذ the.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>Countable: many cars · a few cars · How many cars?</p>\n<p>Uncountable: much water · a little water · How much water?</p>\n<p>General: Cats like fish. · Specific: The cats in our garden like fish.</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. Identify the noun first: countable plural or uncountable?</p>\n<p>2. Check the sentence type: positive → some / a lot of; negative or question → any / much / many.</p>\n<p>3. For articles, ask: Is it general (no article), one of many (a / an) or specific / unique (the)?</p>\n<p>4. Remember fixed phrases: at home, go to school, have lunch, play football — no article.</p>\n<p>5. STEP traps: much + plural, the + general noun, a few + uncountable.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">حدّد نوع الاسم أولًا: معدود أم غير معدود، ثم نوع الجملة: مثبتة أم منفية أم سؤال، وفي أدوات التعريف اسأل: هل الاسم عام أم واحد من كثير أم محدد؟</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. There isn't ______ furniture in the new apartment yet.</strong></p>\n<blockquote>\n<p>A. many B. a few C. some D. much</p>\n<p><strong>Step 1:</strong> furniture is uncountable.</p>\n<p><strong>Step 2:</strong> The sentence is negative.</p>\n<p><strong>Step 3:</strong> Uncountable + negative → much. The answer is D.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">furniture غير معدودة والجملة منفية فنستخدم much.</span></p>\n<p><strong>Example 2. ______ is the closest star to the earth.</strong></p>\n<blockquote>\n<p>A. Sun B. The sun C. A sun D. Suns</p>\n<p><strong>Step 1:</strong> There is only one sun.</p>\n<p><strong>Step 2:</strong> Unique things take the.</p>\n<p><strong>Step 3:</strong> The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الشيء الوحيد من نوعه يأخذ the.</span></p>\n<p><strong>Example 3. (A) <u>The</u> (B) <u>children</u> need (C) <u>a lot of</u> sleep (D) <u>to grow</u> well.</strong></p>\n<blockquote>\n<p>A. The B. children C. a lot of D. to grow</p>\n<p><strong>Step 1:</strong> The sentence talks about children in general.</p>\n<p><strong>Step 2:</strong> General plural nouns take no article.</p>\n<p><strong>Step 3:</strong> Correct: Children need a lot of sleep to grow well. The answer is A.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الحديث عن الأطفال عمومًا فلا نستخدم the.</span></p>","wu":"Warm-up: 1 B · 2 D · 3 B · Worked examples: Example 1 D · Example 2 B · Example 3 A","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"How ______ students are in your class?","o":["much","a little","many","any"],"k":2,"e":"students is countable plural → many.","h":"معدود جمع many."},{"n":2,"s":"I'd like ______ water, please.","o":["any","many","a few","some"],"k":3,"e":"A request in a positive sentence → some.","h":"طلب مثبت some."},{"n":3,"s":"There aren't ______ eggs left.","o":["some","much","a little","any"],"k":3,"e":"Negative + plural → any.","h":"النفي any."},{"n":4,"s":"My uncle is ______ engineer.","o":["a","an","the","—"],"k":1,"e":"Jobs take a / an; engineer starts with a vowel sound → an.","h":"المهنة مع an."},{"n":5,"s":"We don't have ______ time. Let's hurry.","o":["much","many","a few","some"],"k":0,"e":"time is uncountable; negative → much.","h":"غير معدود في النفي much."},{"n":6,"s":"______ moon looks very big tonight.","o":["A","An","—","The"],"k":3,"e":"Only one moon → The.","h":"الشيء الوحيد the."},{"n":7,"s":"Can you add ______ salt to the soup?","o":["a few","many","a little","few"],"k":2,"e":"salt is uncountable → a little.","h":"غير معدود a little."},{"n":8,"s":"I have ______ friends in Dammam. I visit them sometimes.","o":["a few","a little","much","any"],"k":0,"e":"friends is countable plural → a few.","h":"معدود جمع a few."},{"n":9,"s":"______ milk is good for children.","o":["The","A","—","Some of"],"k":2,"e":"General uncountable noun → no article.","h":"الاسم العام بلا أداة."},{"n":10,"s":"Have you got ______ questions about the homework?","o":["some of","much","a little","any"],"k":3,"e":"Question + plural → any.","h":"السؤال any."},{"n":11,"s":"There are ______ cars on the road at rush hour.","o":["much","a little","a lot of","any"],"k":2,"e":"Positive + plural → a lot of.","h":"مثبت جمع a lot of."},{"n":12,"s":"I saw a camel near the road. ______ camel was drinking water.","o":["A","The","An","—"],"k":1,"e":"Second mention → the.","h":"الذكر الثاني the."},{"n":13,"s":"How ______ money did you spend at the mall?","o":["many","few","a few","much"],"k":3,"e":"money is uncountable → much.","h":"money غير معدودة."},{"n":14,"s":"We usually have ______ lunch at 1 p.m.","o":["—","the","a","an"],"k":0,"e":"Meals take no article.","h":"الوجبات بلا أداة."},{"n":15,"s":"My brother plays ______ basketball every evening.","o":["the","a","—","an"],"k":2,"e":"Sports take no article.","h":"الرياضات بلا أداة."},{"n":16,"s":"There is ______ information on this website.","o":["many","a lot of","a few","much of"],"k":1,"e":"information is uncountable; positive → a lot of.","h":"غير معدود في المثبت a lot of."},{"n":17,"s":"______ Red Sea is famous for its coral reefs.","o":["The","A","—","An"],"k":0,"e":"Seas take the.","h":"البحار تأخذ the."},{"n":18,"s":"Only ______ people came to the meeting, so it was very quiet.","o":["a little","much","few of","a few"],"k":3,"e":"people is countable plural → a few.","h":"معدود جمع."},{"n":19,"s":"Is there ______ juice left in the bottle?","o":["many","a few","any","some of"],"k":2,"e":"Question + uncountable → any.","h":"سؤال مع غير معدود any."},{"n":20,"s":"Please close ______ door. It's cold in here.","o":["the","a","an","—"],"k":0,"e":"Both speakers know which door (the one in this room) → the.","h":"الباب معروف للمتحدثين the."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"I don't (A) have (B) many (C) free time this (D) week.","o":["have","many","free","week"],"k":1,"e":"time is uncountable → much.","h":""},{"n":22,"s":"(A) The honey (B) is good (C) for your (D) health.","o":["The","is","for","health"],"k":0,"e":"General uncountable noun → no the.","h":""},{"n":23,"s":"There (A) aren't (B) some (C) apples in (D) the fridge.","o":["aren't","some","apples","the"],"k":1,"e":"Negative → any.","h":""},{"n":24,"s":"Can I (A) have (B) a few (C) milk in my (D) coffee?","o":["have","a few","milk","coffee"],"k":1,"e":"milk is uncountable → a little.","h":""},{"n":25,"s":"My sister (A) is (B) a doctor, and she works (C) in (D) a King Fahd Hospital.","o":["is","a","in","a"],"k":3,"e":"Most named hospitals take no article.","h":""},{"n":26,"s":"How (A) much (B) children (C) are there (D) in your family?","o":["much","children","are","in"],"k":0,"e":"children is countable plural → many.","h":""},{"n":27,"s":"We (A) watched (B) the (C) sunset from (D) a top of the mountain.","o":["watched","the","sunset","a"],"k":3,"e":"the top of the mountain is specific → the.","h":""},{"n":28,"s":"He (A) goes (B) to the school (C) by bus (D) every day.","o":["goes","to the school","by","every"],"k":1,"e":"go to school (as a student) has no article.","h":""},{"n":29,"s":"(A) A (B) little students (C) were late (D) because of the rain.","o":["A","little","were","because of"],"k":1,"e":"students is countable → a few.","h":""},{"n":30,"s":"Riyadh (A) is (B) the capital of (C) the Saudi Arabia, and it is (D) very big.","o":["is","the","the","very"],"k":2,"e":"Saudi Arabia takes no article.","h":""}]}],"n":30},{"id":"2.8","t":"Zero and First Conditionals + Time Clauses (when, before, after, as soon as)","html":"<p><strong>Unit 2 · Lesson 2.8 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Form the zero conditional for facts and the first conditional for real future possibilities.</p>\n<p>2. Use a present tense after when, before, after and as soon as with future meaning.</p>\n<p>3. Avoid will in the if-clause or the time clause.</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يكوّن الطالب الجملة الشرطية الصفرية للحقائق، والشرطية الأولى للاحتمالات الحقيقية في المستقبل.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يستخدم المضارع بعد when وbefore وafter وas soon as بمعنى المستقبل.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يتجنب استخدام will في جملة الشرط أو جملة الزمن.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. If you heat ice, it ______.</strong></p>\n<blockquote>\n<p>A. will melt B. melted C. melts D. melting</p>\n</blockquote>\n<p><strong>2. If it rains tomorrow, we ______ at home.</strong></p>\n<blockquote>\n<p>A. will stay B. stay C. stayed D. staying</p>\n</blockquote>\n<p><strong>3. I'll call you when I ______ home.</strong></p>\n<blockquote>\n<p>A. will get B. got C. getting D. get</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>Zero conditional (facts, general truths)</strong></p>\n<p><strong>If / When + present simple, present simple</strong></p>\n<p><em>e.g. If you mix blue and yellow, you get green.</em></p>\n<p><strong>First conditional (real future)</strong></p>\n<p><strong>If + present simple, will / won't + base verb</strong></p>\n<p><em>e.g. If you study, you will pass.</em></p>\n<p><strong>Clause order</strong></p>\n<p><strong>Result + if + condition (no comma) · If + condition, + result (comma)</strong></p>\n<p><em>e.g. You will pass if you study. / If you study, you will pass.</em></p>\n<p><strong>unless = if … not</strong></p>\n<p><strong>unless + present simple, will …</strong></p>\n<p><em>e.g. You'll be late unless you hurry. (= if you don't hurry)</em></p>\n<p><strong>Future time clauses</strong></p>\n<p><strong>when / before / after / as soon as / until + present simple, will …</strong></p>\n<p><em>e.g. I'll phone you as soon as I land.</em></p>\n<p><strong>Other result forms</strong></p>\n<p><strong>If + present, can / may / must / imperative</strong></p>\n<p><em>e.g. If you finish early, you can go home. If you see Ali, tell him to call me.</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. Zero conditional: always true.</strong></p>\n<p>We use it for scientific facts and things that always happen.</p>\n<blockquote>\n<p>▸ If you heat water to 100°C, it boils.</p>\n<p>▸ Plants die if they don't get water.</p>\n<p>▸ When I drink coffee at night, I can't sleep.</p>\n</blockquote>\n<p><strong>2. First conditional: a real possibility in the future.</strong></p>\n<p>The situation is possible, and we talk about its likely result.</p>\n<blockquote>\n<p>▸ If it rains tomorrow, the match will be cancelled.</p>\n<p>▸ If you don't hurry, you'll miss the bus.</p>\n<p>▸ We'll go to the beach if the weather is nice.</p>\n</blockquote>\n<p><strong>3. Time clauses about the future.</strong></p>\n<p>After when, before, after, as soon as and until, we use the present simple, but the meaning is future.</p>\n<blockquote>\n<p>▸ I'll call you when I arrive in Jeddah.</p>\n<p>▸ Before you leave, please turn off the lights.</p>\n<p>▸ As soon as the results come out, I'll tell you.</p>\n<p>▸ We'll wait here until the rain stops.</p>\n</blockquote>\n<p><strong>4. if vs when.</strong></p>\n<p>if = maybe it will happen; when = we are sure it will happen.</p>\n<blockquote>\n<p>▸ If I see Huda, I'll give her the book. (maybe I will see her)</p>\n<p>▸ When I see Huda tomorrow, I'll give her the book. (I will see her)</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ NEVER put will after if / when / before / after / as soon as / unless in these sentences.</p>\n<p>▸ Use a comma when the if-clause comes first.</p>\n<p>▸ unless already contains not: ✗ unless you don't hurry ✓ unless you hurry.</p>\n<p>▸ In the zero conditional, if and when have almost the same meaning.</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الجملة الشرطية الصفرية تتكون من If + المضارع البسيط ثم المضارع البسيط، وتعبّر عن حقائق علمية أو أمور تحدث دائمًا.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الجملة الشرطية الأولى تتكون من If + المضارع البسيط ثم will مع الفعل الأصلي، وتعبّر عن احتمال حقيقي في المستقبل، ولا نستخدم will بعد if.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">وبعد كلمات الزمن when وbefore وafter وas soon as وuntil نستخدم المضارع البسيط مع أن المعنى مستقبل، وكلمة unless تعني if … not.</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>If it will rain, we will stay home.</em> <strong>→ ✓ If it rains, we will stay home.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لا نستخدم will بعد if.</span></p>\n<p><strong>✗</strong> <em>I will call you when I will arrive.</em> <strong>→ ✓ I will call you when I arrive.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد when نستخدم المضارع للمستقبل.</span></p>\n<p><strong>✗</strong> <em>If you will heat ice, it melts.</em> <strong>→ ✓ If you heat ice, it melts.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الحقائق بالمضارع في الجملتين.</span></p>\n<p><strong>✗</strong> <em>Unless you don't study, you will fail.</em> <strong>→ ✓ Unless you study, you will fail.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">unless تحمل معنى النفي.</span></p>\n<p><strong>✗</strong> <em>If you study, you pass the exam tomorrow.</em> <strong>→ ✓ If you study, you will pass the exam tomorrow.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">النتيجة المستقبلية تحتاج will.</span></p>\n<p><strong>✗</strong> <em>As soon as I will finish, I'll call you.</em> <strong>→ ✓ As soon as I finish, I'll call you.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد as soon as المضارع البسيط.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>Zero: If you press this button, the machine stops. (always)</p>\n<p>First: If you press this button, the machine will stop. (this time, in the future)</p>\n<p>Time clause: When you press the button, the machine will stop.</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. Find the if / when / before / as soon as clause: its verb is present simple (no will).</p>\n<p>2. Find the result clause: always true → present; future → will / won't + base verb.</p>\n<p>3. unless = if not; check that the sentence does not have a double negative.</p>\n<p>4. If the comma separates the clauses, the if-clause is first.</p>\n<p>5. STEP error items often hide will inside the if-clause or time clause.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">حدّد جملة الشرط أو الزمن واجعل فعلها في المضارع البسيط دون will، ثم حدّد جملة النتيجة: حقيقة دائمة بالمضارع، ومستقبل بـ will.</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. If you ______ the green button, the door opens.</strong></p>\n<blockquote>\n<p>A. will press B. press C. pressed D. are pressing</p>\n<p><strong>Step 1:</strong> The result (the door opens) is present simple — a general fact.</p>\n<p><strong>Step 2:</strong> Zero conditional: If + present, present.</p>\n<p><strong>Step 3:</strong> The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">حقيقة دائمة: المضارع في الجملتين.</span></p>\n<p><strong>Example 2. We ______ the match if our best player is injured.</strong></p>\n<blockquote>\n<p>A. lose B. would lose C. will lose D. lost</p>\n<p><strong>Step 1:</strong> The if-clause is present simple (is injured) about the future.</p>\n<p><strong>Step 2:</strong> First conditional result → will + base verb.</p>\n<p><strong>Step 3:</strong> The answer is C.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">احتمال مستقبلي: النتيجة will.</span></p>\n<p><strong>Example 3. (A) <u>Please</u> (B) <u>send</u> me a message as soon as you (C) <u>will reach</u> (D) <u>the</u> hotel.</strong></p>\n<blockquote>\n<p>A. Please B. send C. will reach D. the</p>\n<p><strong>Step 1:</strong> as soon as introduces a future time clause.</p>\n<p><strong>Step 2:</strong> Time clauses use present simple, not will.</p>\n<p><strong>Step 3:</strong> Correct: Please send me a message as soon as you reach the hotel. The answer is C.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد as soon as نستخدم المضارع البسيط.</span></p>","wu":"Warm-up: 1 C · 2 A · 3 D · Worked examples: Example 1 B · Example 2 C · Example 3 C","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"If you heat water to 100°C, it ______.","o":["boils","will boils","boiled","boiling"],"k":0,"e":"Scientific fact → present simple.","h":"حقيقة علمية بالمضارع."},{"n":2,"s":"If it ______ tomorrow, we will go to the park.","o":["won't rain","didn't rain","doesn't rain","not rain"],"k":2,"e":"if-clause → present simple (negative).","h":"جملة الشرط بالمضارع."},{"n":3,"s":"If you study hard, you ______ the test.","o":["will pass","pass will","passed","passing"],"k":0,"e":"Future result → will + base verb.","h":"النتيجة will."},{"n":4,"s":"I'll phone you when I ______ at the airport.","o":["will arrive","arrived","arrive","arriving"],"k":2,"e":"After when (future) → present simple.","h":"بعد when المضارع."},{"n":5,"s":"Ice ______ if you leave it in the sun.","o":["melted","will melting","is melt","melts"],"k":3,"e":"General fact → present simple.","h":"حقيقة عامة."},{"n":6,"s":"If you see Turki, ______ him I'm waiting.","o":["you tell","tell","will tell to","telling"],"k":1,"e":"If + present, imperative result.","h":"النتيجة بصيغة الأمر."},{"n":7,"s":"We'll start the meeting as soon as everyone ______.","o":["arrives","will arrive","arrive","arrived"],"k":0,"e":"After as soon as → present simple; everyone is singular → arrives.","h":"بعد as soon as المضارع، وeveryone مفرد."},{"n":8,"s":"You'll be late ______ you hurry.","o":["if","when","unless","as soon as"],"k":2,"e":"Late if you don't hurry → unless.","h":"unless = if not."},{"n":9,"s":"Before you ______ the house, turn off the air conditioner.","o":["will leave","left","leaving","leave"],"k":3,"e":"After before (future instruction) → present simple.","h":"بعد before المضارع."},{"n":10,"s":"If my father ______ time, he will help me with my project.","o":["will have","had","have","has"],"k":3,"e":"if-clause → present simple; my father → has.","h":"جملة الشرط بالمضارع."},{"n":11,"s":"If you don't water plants, they ______.","o":["will died","died","die","dying"],"k":2,"e":"General truth → present simple.","h":"حقيقة عامة."},{"n":12,"s":"I won't go out until the rain ______.","o":["will stop","stops","stopped","stop"],"k":1,"e":"After until (future) → present simple; the rain → stops.","h":"بعد until المضارع."},{"n":13,"s":"If we miss the bus, we ______ a taxi.","o":["take will","will take","took","taking"],"k":1,"e":"First conditional result → will take.","h":"النتيجة will."},{"n":14,"s":"When I ______ coffee in the evening, I can't sleep.","o":["will drink","drank","drinking","drink"],"k":3,"e":"A general habit (zero conditional) → present simple.","h":"عادة عامة بالمضارع."},{"n":15,"s":"She ______ angry if you forget her birthday again.","o":["will be","is being","be","would being"],"k":0,"e":"Future result → will be.","h":"النتيجة المستقبلية will be."},{"n":16,"s":"If you mix red and white, you ______ pink.","o":["will got","got","get","getting"],"k":2,"e":"Fact → present simple.","h":"حقيقة بالمضارع."},{"n":17,"s":"Unless the weather ______, the flight will leave on time.","o":["doesn't change","changes","will change","won't change"],"k":1,"e":"unless already means if not → positive present verb.","h":"unless تحمل النفي."},{"n":18,"s":"After you ______ your homework, you can play video games.","o":["finish","will finish","finished","finishing"],"k":0,"e":"After + present simple for future.","h":"بعد after المضارع."},{"n":19,"s":"If the shop is closed, we ______ buy bread tomorrow.","o":["can to","will can","could to","can"],"k":3,"e":"If + present, can + base verb.","h":"النتيجة can."},{"n":20,"s":"I'll tell you the news ______ I hear anything.","o":["as soon as","unless","until","before that"],"k":0,"e":"Immediately when → as soon as.","h":"فور ما as soon as."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"If it (A) will be sunny (B) tomorrow, we (C) will (D) go to the beach.","o":["will be","tomorrow","will","go"],"k":0,"e":"No will after if.","h":""},{"n":22,"s":"When you (A) heat (B) ice, it (C) will melt and (D) becomes water.","o":["heat","ice","will melt","becomes"],"k":2,"e":"A fact (zero conditional) → present simple melts.","h":""},{"n":23,"s":"(A) I (B) will text you (C) as soon as I (D) will land.","o":["I","will","as soon as","will land"],"k":3,"e":"After as soon as → present simple.","h":""},{"n":24,"s":"If you (A) don't (B) will hurry, you (C) will (D) miss the train.","o":["don't","will hurry","will","miss"],"k":1,"e":"No will in the if-clause.","h":""},{"n":25,"s":"(A) Unless you (B) don't (C) practise, you (D) won't improve.","o":["Unless","don't","practise","won't"],"k":1,"e":"unless already means if not.","h":""},{"n":26,"s":"We (A) will wait (B) here (C) until the bus (D) will come.","o":["will","here","until","will come"],"k":3,"e":"After until → present simple.","h":""},{"n":27,"s":"If you (A) mixed blue (B) and yellow, you (C) get (D) green.","o":["mixed","and","get","green"],"k":0,"e":"Zero conditional → present simple mix.","h":""},{"n":28,"s":"If Sara (A) passes the exam, her parents (B) are (C) buy her a (D) new phone.","o":["passes","are","buy","new"],"k":2,"e":"Future result → will buy.","h":""},{"n":29,"s":"(A) Before you (B) will go to bed, (C) brush your (D) teeth.","o":["Before","will go","brush","teeth"],"k":1,"e":"After before → present simple.","h":""},{"n":30,"s":"If the (A) traffic (B) is heavy, we (C) will (D) arriving late.","o":["traffic","is","will","arriving"],"k":3,"e":"will + base form arrive.","h":""}]}],"n":30},{"id":"2.9","t":"Verb Patterns (-ing / to-infinitive), Adverbs of Manner, too / enough","html":"<p><strong>Unit 2 · Lesson 2.9 · CEFR A2 · STEP link: Sentence Structure (completion + error identification)</strong></p>\n<h3>Objectives</h3>\n<p>1. Use -ing after enjoy, finish, avoid, mind and the to-infinitive after want, decide, hope, plan.</p>\n<p>2. Form adverbs of manner, including irregular ones (well, hard, fast).</p>\n<p>3. Use too + adjective and adjective + enough correctly.</p>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">الأهداف</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">١. أن يستخدم الطالب صيغة ing بعد enjoy وfinish وavoid وmind، وصيغة to بعد want وdecide وhope وplan.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٢. أن يكوّن ظروف الحال بما فيها الشاذة مثل well وhard وfast.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">٣. أن يستخدم too قبل الصفة وenough بعد الصفة استخدامًا صحيحًا.</span></p>\n<h3>Warm-up (not counted in the quiz)</h3>\n<p><strong>1. I enjoy ______ football with my friends.</strong></p>\n<blockquote>\n<p>A. to play B. play C. playing D. played</p>\n</blockquote>\n<p><strong>2. She wants ______ a doctor.</strong></p>\n<blockquote>\n<p>A. to become B. becoming C. become D. becomes</p>\n</blockquote>\n<p><strong>3. This tea is ______ hot to drink.</strong></p>\n<blockquote>\n<p>A. enough B. very C. so D. too</p>\n</blockquote>\n<h3>Form</h3>\n<blockquote>\n<p><strong>Verb + -ing</strong></p>\n<p><strong>enjoy · finish · avoid · mind · keep · practise · stop · suggest · miss · can't stand</strong></p>\n<p><em>e.g. I finished reading the book. Do you mind waiting?</em></p>\n<p><strong>Verb + to-infinitive</strong></p>\n<p><strong>want · decide · hope · plan · need · learn · agree · promise · refuse · would like · try (= make an effort)</strong></p>\n<p><em>e.g. We decided to leave early. He promised to help.</em></p>\n<p><strong>Verb + object + to-infinitive</strong></p>\n<p><strong>want / ask / tell / help / allow + someone + to + verb</strong></p>\n<p><em>e.g. My father wants me to study medicine.</em></p>\n<p><strong>Preposition + -ing</strong></p>\n<p><strong>good at · interested in · afraid of · tired of · before / after / without + -ing</strong></p>\n<p><em>e.g. She is good at drawing. Wash your hands before eating.</em></p>\n<p><strong>Adverbs of manner</strong></p>\n<p><strong>adjective + -ly: slow → slowly · careful → carefully · easy → easily · gentle → gently</strong></p>\n<p><em>e.g. Please drive carefully.</em></p>\n<p><strong>Irregular adverbs</strong></p>\n<p><strong>good → well · fast → fast · hard → hard · late → late · early → early</strong></p>\n<p><em>e.g. He speaks English well. She works hard.</em></p>\n<p><strong>too / enough</strong></p>\n<p><strong>too + adjective (+ to + verb) · adjective + enough (+ to + verb) · enough + noun</strong></p>\n<p><em>e.g. It's too cold to swim. He isn't old enough to drive. We have enough time.</em></p>\n</blockquote>\n<h3>Use</h3>\n<p><strong>1. -ing after certain verbs.</strong></p>\n<p>Some verbs are always followed by the -ing form.</p>\n<blockquote>\n<p>▸ My grandfather enjoys walking in the evening.</p>\n<p>▸ Have you finished cleaning your room?</p>\n<p>▸ Try to avoid eating fast food.</p>\n</blockquote>\n<p><strong>2. to-infinitive after other verbs.</strong></p>\n<p>Verbs about plans, wishes and decisions usually take to + verb.</p>\n<blockquote>\n<p>▸ I hope to visit Japan one day.</p>\n<p>▸ They decided to buy a bigger car.</p>\n<p>▸ My sister is learning to drive.</p>\n</blockquote>\n<p><strong>3. Adverbs of manner describe HOW we do something.</strong></p>\n<p>Adjectives describe nouns; adverbs describe verbs.</p>\n<blockquote>\n<p>▸ Huda is a careful driver. She drives carefully.</p>\n<p>▸ Turki is a fast runner. He runs fast.</p>\n<p>▸ You did the test very well.</p>\n</blockquote>\n<p><strong>4. too and enough.</strong></p>\n<p>too means more than we want; enough means as much as we need.</p>\n<blockquote>\n<p>▸ The box is too heavy for me to carry.</p>\n<p>▸ This room isn't big enough for ten people.</p>\n<p>▸ Do we have enough chairs for the guests?</p>\n</blockquote>\n<h3>Signal Words and Notes</h3>\n<p>▸ good is an adjective; well is the adverb: She sings well. (not She sings good)</p>\n<p>▸ hardly means almost not — it is NOT the adverb of hard: He works hard. (not hardly)</p>\n<p>▸ enough goes AFTER adjectives but BEFORE nouns: tall enough · enough money.</p>\n<p>▸ too is negative in meaning; very is not: It's very hot (but I can drink it). It's too hot (I can't drink it).</p>\n<h3>Arabic Explanation</h3>\n<p class=\"ar\" dir=\"rtl\"><strong><span dir=\"rtl\" lang=\"ar\">شرح القاعدة بالعربية</span></strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعض الأفعال يأتي بعدها الفعل بصيغة ing مثل enjoy وfinish وavoid وmind، وبعضها يأتي بعده to مع الفعل مثل want وdecide وhope وplan، ويجب حفظ هذه الأفعال. وبعد حروف الجر نستخدم ing دائمًا.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">ظرف الحال يصف كيف يحدث الفعل، ونكوّنه غالبًا بإضافة ly إلى الصفة مثل slowly، وهناك ظروف شاذة مثل well من good، وhard وfast دون تغيير.</span></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">too تأتي قبل الصفة وتعني «أكثر من اللازم»، وenough تأتي بعد الصفة وقبل الاسم وتعني «بالقدر الكافي».</span></p>\n<h3>Arab Learner Alert</h3>\n<blockquote>\n<p><strong>✗</strong> <em>I enjoy to swim.</em> <strong>→ ✓ I enjoy swimming.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد enjoy نستخدم ing.</span></p>\n<p><strong>✗</strong> <em>I want going home.</em> <strong>→ ✓ I want to go home.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">بعد want نستخدم to.</span></p>\n<p><strong>✗</strong> <em>He speaks English very good.</em> <strong>→ ✓ He speaks English very well.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لوصف الفعل نستخدم الظرف well.</span></p>\n<p><strong>✗</strong> <em>She drives careful.</em> <strong>→ ✓ She drives carefully.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">الظرف يُكوَّن بإضافة ly.</span></p>\n<p><strong>✗</strong> <em>He is enough old to drive.</em> <strong>→ ✓ He is old enough to drive.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">enough تأتي بعد الصفة.</span></p>\n<p><strong>✗</strong> <em>It is too much hot.</em> <strong>→ ✓ It is too hot.</strong></p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">too تأتي مباشرة قبل الصفة.</span></p>\n</blockquote>\n<h3>Compare and Contrast</h3>\n<blockquote>\n<p>enjoy + -ing: I enjoy reading. · want + to: I want to read.</p>\n<p>adjective: a quick lunch · adverb: eat quickly</p>\n<p>too + adj: too small · adj + enough: big enough · enough + noun: enough space</p>\n</blockquote>\n<h3>STEP Strategy</h3>\n<blockquote>\n<p>1. Look at the verb BEFORE the blank: enjoy / finish / avoid → -ing; want / decide / hope → to.</p>\n<p>2. After a preposition (at, in, of, before, after, without) → -ing.</p>\n<p>3. If the blank describes a verb, choose an adverb (-ly, well, hard, fast).</p>\n<p>4. Position check: too + adjective; adjective + enough; enough + noun.</p>\n<p>5. STEP traps: speak English good, drive careful, enough old, enjoy to.</p>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">انظر إلى الفعل قبل الفراغ لتعرف هل يأتي بعده ing أم to، وبعد حروف الجر نستخدم ing، وإذا كان الفراغ يصف فعلًا فاختر الظرف.</span></p>\n</blockquote>\n<h3>Worked STEP Examples (not counted in the quiz)</h3>\n<p><strong>Example 1. My brother has decided ______ engineering at university.</strong></p>\n<blockquote>\n<p>A. studying B. study C. to study D. studies</p>\n<p><strong>Step 1:</strong> The verb before the blank is decide.</p>\n<p><strong>Step 2:</strong> decide + to-infinitive.</p>\n<p><strong>Step 3:</strong> The answer is C.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">decide يأتي بعده to.</span></p>\n<p><strong>Example 2. The children were playing ______ in the garden.</strong></p>\n<blockquote>\n<p>A. quiet B. quietly C. quieter D. quietness</p>\n<p><strong>Step 1:</strong> The blank describes how they were playing (a verb).</p>\n<p><strong>Step 2:</strong> To describe a verb we use an adverb.</p>\n<p><strong>Step 3:</strong> quiet → quietly. The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">لوصف الفعل نستخدم الظرف quietly.</span></p>\n<p><strong>Example 3. Majed (A) <u>is</u> not (B) <u>enough tall</u> (C) <u>to play</u> (D) <u>in</u> the basketball team.</strong></p>\n<blockquote>\n<p>A. is B. enough tall C. to play D. in</p>\n<p><strong>Step 1:</strong> enough goes after an adjective.</p>\n<p><strong>Step 2:</strong> enough tall → tall enough.</p>\n<p><strong>Step 3:</strong> Correct: Majed is not tall enough to play in the basketball team. The answer is B.</p>\n</blockquote>\n<p class=\"ar\" dir=\"rtl\"><span dir=\"rtl\" lang=\"ar\">enough تأتي بعد الصفة.</span></p>","wu":"Warm-up: 1 C · 2 A · 3 D · Worked examples: Example 1 C · Example 2 B · Example 3 B","quiz":[{"l":["Answer all 30 questions. Choose the best answer (A, B, C or D).","أجب عن الأسئلة الثلاثين جميعها، واختر الإجابة الصحيحة من بين البدائل الأربعة.","Part A — Sentence Completion (Questions 1–20): Choose the word or phrase that best completes the sentence.","الجزء الأول: اختر الكلمة أو العبارة التي تكمل الجملة إكمالًا صحيحًا."],"q":[{"n":1,"s":"I enjoy ______ to the beach with my family.","o":["to go","going","go","went"],"k":1,"e":"enjoy + -ing.","h":"enjoy مع ing."},{"n":2,"s":"We want ______ AlUla next spring.","o":["visiting","visit","to visit","visited"],"k":2,"e":"want + to-infinitive.","h":"want مع to."},{"n":3,"s":"Please speak ______. The baby is sleeping.","o":["quietly","quiet","quieter","quietness"],"k":0,"e":"Describes how to speak → adverb.","h":"يصف الفعل → ظرف."},{"n":4,"s":"This coffee is ______ hot. I can't drink it.","o":["enough","very much","so much","too"],"k":3,"e":"More than I want → too.","h":"أكثر من اللازم too."},{"n":5,"s":"Have you finished ______ your report?","o":["to write","write","writing","wrote"],"k":2,"e":"finish + -ing.","h":"finish مع ing."},{"n":6,"s":"My sister plays the piano very ______.","o":["well","good","goodly","better well"],"k":0,"e":"Describes a verb → well.","h":"الظرف من good هو well."},{"n":7,"s":"He hopes ______ a pilot one day.","o":["becoming","become","to become","became"],"k":2,"e":"hope + to-infinitive.","h":"hope مع to."},{"n":8,"s":"Is your brother old ______ to drive?","o":["too","very","so","enough"],"k":3,"e":"adjective + enough.","h":"enough بعد الصفة."},{"n":9,"s":"Ali is a careful driver. He drives ______.","o":["carefully","careful","carefuly","care"],"k":0,"e":"careful → carefully.","h":"ظرف الحال carefully."},{"n":10,"s":"Do you mind ______ the window? It's hot in here.","o":["opening","to open","open","opened"],"k":0,"e":"mind + -ing.","h":"mind مع ing."},{"n":11,"s":"My parents decided ______ a new house near the school.","o":["buying","buy","to buy","bought"],"k":2,"e":"decide + to.","h":"decide مع to."},{"n":12,"s":"She worked very ______ and passed all her exams.","o":["hardly","hardy","harder than","hard"],"k":3,"e":"hard is both adjective and adverb; hardly means almost not.","h":"الظرف من hard هو hard."},{"n":13,"s":"We don't have ______ chairs for all the guests.","o":["too","enough","too much","very"],"k":1,"e":"enough + noun.","h":"enough قبل الاسم."},{"n":14,"s":"Try to avoid ______ in the sun at midday.","o":["to walk","walking","walk","walked"],"k":1,"e":"avoid + -ing.","h":"avoid مع ing."},{"n":15,"s":"My teacher told me ______ more English books.","o":["reading","read","reads","to read"],"k":3,"e":"tell + object + to-infinitive.","h":"tell + مفعول + to."},{"n":16,"s":"The test was ______ easy that everyone finished early.","o":["too","enough","so","such"],"k":2,"e":"so + adjective + that.","h":"so … that."},{"n":17,"s":"Hessa is interested in ______ about space.","o":["to learn","learning","learn","learned"],"k":1,"e":"After the preposition in → -ing.","h":"بعد حرف الجر ing."},{"n":18,"s":"The bag is too heavy ______.","o":["to me carrying","for me carrying","for me to carry","that I carry it"],"k":2,"e":"too + adjective + for + person + to + verb.","h":"too + for + to."},{"n":19,"s":"Please answer the questions as ______ as you can.","o":["quickly","quick","quicker","quickness"],"k":0,"e":"as + adverb + as to describe answer.","h":"ظرف بين as … as."},{"n":20,"s":"I'd like ______ my cousins in Madinah this weekend.","o":["seeing","see","to see","seen"],"k":2,"e":"would like + to-infinitive.","h":"would like مع to."}]},{"l":["Part B — Error Identification (Questions 21–30): Each sentence has four underlined parts (A, B, C, D). Choose the ONE part that is incorrect.","الجزء الثاني: في كل جملة أربعة أجزاء تحتها خط، اختر الجزء الذي يحتوي على خطأ."],"q":[{"n":21,"s":"I (A) enjoy (B) to read stories (C) before I go (D) to sleep.","o":["enjoy","to read","before","to"],"k":1,"e":"enjoy + -ing.","h":""},{"n":22,"s":"My (A) brother lived (B) in Paris, so he (C) speaks French very (D) good.","o":["brother","in","speaks","good"],"k":3,"e":"Describes a verb → well.","h":""},{"n":23,"s":"She (A) wants (B) visiting her (C) grandparents (D) this weekend.","o":["wants","visiting","grandparents","this"],"k":1,"e":"want + to-infinitive.","h":""},{"n":24,"s":"This water (A) isn't enough warm (B) for (C) swimming (D) today.","o":["isn't enough warm","for","swimming","today"],"k":0,"e":"adjective + enough.","h":""},{"n":25,"s":"On the wet (A) road he (B) drove very (C) slowly and (D) careful.","o":["road","drove","slowly","careful"],"k":3,"e":"Both words describe the verb drove → carefully.","h":""},{"n":26,"s":"(A) Have you (B) finished (C) to clean your (D) room?","o":["Have","finished","to clean","room"],"k":2,"e":"finish + -ing.","h":""},{"n":27,"s":"Our classroom (A) was too much small (B) for (C) thirty (D) students.","o":["was too much small","for","thirty","students"],"k":0,"e":"too + adjective (no much).","h":""},{"n":28,"s":"(A) Thank you for (B) help me (C) with my (D) homework.","o":["Thank","help","with","homework"],"k":1,"e":"After the preposition for → -ing.","h":""},{"n":29,"s":"My (A) mother (B) told (C) my sister (D) tidy her room.","o":["mother","told","my sister","tidy"],"k":3,"e":"tell + object + to-infinitive.","h":""},{"n":30,"s":"Omar (A) works (B) hardly every day, (C) so he is always (D) tired.","o":["works","hardly","so","tired"],"k":1,"e":"The adverb of hard is hard; hardly means almost not.","h":""}]}],"n":30}],"sc":{},"review":{"quiz":[{"l":["Unit Review — 50 questions. Questions 1–35: choose the word or phrase that best completes the sentence. Questions 36–50: choose the ONE underlined part that is incorrect.","مراجعة الوحدة: خمسون سؤالًا؛ في الأسئلة من ١ إلى ٣٥ اختر الإجابة التي تكمل الجملة، وفي الأسئلة من ٣٦ إلى ٥٠ اختر الجزء الذي يحتوي على خطأ.","Part A — Sentence Completion (Questions 1–35)"],"q":[{"n":1,"s":"We ______ at my aunt's house last Friday.","o":["was","are","were","did"],"k":2,"e":"we + past → were.","h":"we في الماضي were."},{"n":2,"s":"I ______ a new jacket at the mall yesterday.","o":["buyed","buy","brought","bought"],"k":3,"e":"buy → bought.","h":"ماضي buy هو bought."},{"n":3,"s":"\"Can you help me?\" \"Sure, I ______ help you.\"","o":["'m going to","'ll","am","help"],"k":1,"e":"An instant offer → will.","h":"عرض لحظي will."},{"n":4,"s":"My bag is ______ than yours.","o":["heavyer","more heavy","heaviest","heavier"],"k":3,"e":"heavy → heavier.","h":"heavier."},{"n":5,"s":"I have ______ finished my breakfast.","o":["yet","just","ever","since"],"k":1,"e":"just before the participle.","h":"just قبل التصريف الثالث."},{"n":6,"s":"You ______ eat in the library. It's against the rules.","o":["don't have to","must","mustn't","should"],"k":2,"e":"Against the rules → mustn't.","h":"ممنوع."},{"n":7,"s":"How ______ bottles of water do we need?","o":["many","much","a little","any of"],"k":0,"e":"bottles is countable → many.","h":"معدود جمع."},{"n":8,"s":"If you heat butter, it ______.","o":["will melts","melted","melts","melting"],"k":2,"e":"Fact → present simple.","h":"حقيقة بالمضارع."},{"n":9,"s":"My little brother wants ______ a pilot.","o":["being","to be","be","is"],"k":1,"e":"want + to.","h":"want مع to."},{"n":10,"s":"There ______ a strong wind last night.","o":["was","were","is","had"],"k":0,"e":"a strong wind is singular; past → was.","h":"مفرد في الماضي."},{"n":11,"s":"Did you ______ the football match on TV?","o":["watch","watched","watches","watching"],"k":0,"e":"Did + base form.","h":"بعد Did الفعل الأصلي."},{"n":12,"s":"Look at the traffic! We ______ be late.","o":["will to","are","go to","are going to"],"k":3,"e":"Evidence now → are going to.","h":"دليل حاضر."},{"n":13,"s":"This is the ______ beach in Yanbu.","o":["most clean","cleaner","cleanest","more clean"],"k":2,"e":"the … in → superlative of a short adjective.","h":"التفضيل للصفة القصيرة."},{"n":14,"s":"Have you ______ been to the Edge of the World?","o":["yet","ever","already","since"],"k":1,"e":"Experience question → ever.","h":"سؤال التجربة ever."},{"n":15,"s":"Tomorrow is a holiday, so we ______ wake up early.","o":["mustn't","have to","don't have to","must to"],"k":2,"e":"Not necessary → don't have to.","h":"ليس ضروريًا."},{"n":16,"s":"I need ______ help with this heavy table.","o":["a few","many","few of","a little"],"k":3,"e":"help is uncountable → a little.","h":"غير معدود a little."},{"n":17,"s":"I'll wait at the gate until you ______.","o":["will come","came","are coming to","come"],"k":3,"e":"After until (future) → present simple.","h":"بعد until المضارع."},{"n":18,"s":"She speaks Arabic and English very ______.","o":["well","good","goodly","nice"],"k":0,"e":"Describes speaks → well.","h":"الظرف well."},{"n":19,"s":"\"Were you tired after the trip?\" \"Yes, I ______.\"","o":["were","did","was","am"],"k":2,"e":"Short answer with I → Yes, I was.","h":"الإجابة القصيرة Yes, I was."},{"n":20,"s":"Where ______ your family go for Eid last year?","o":["did","do","was","were"],"k":0,"e":"Past Wh- question with go → did.","h":"السؤال في الماضي did."},{"n":21,"s":"I'm seeing the dentist ______ 4 p.m. tomorrow.","o":["at","on","in","by the"],"k":0,"e":"Arranged future with a clock time → at.","h":"الساعة مع at."},{"n":22,"s":"My English is not as ______ as my sister's.","o":["better","good","best","well than"],"k":1,"e":"not as + basic adjective + as.","h":"الصفة الأصلية مع as."},{"n":23,"s":"We ______ in this house since 2015.","o":["live","lived","are living","have lived"],"k":3,"e":"Up to now (since 2015) → present perfect.","h":"من الماضي حتى الآن."},{"n":24,"s":"You ______ wear a heavy coat. It's not cold today.","o":["mustn't","must","don't need to","should to"],"k":2,"e":"Not necessary → don't need to.","h":"ليس ضروريًا."},{"n":25,"s":"______ Arabian Gulf is east of Riyadh.","o":["The","A","An","—"],"k":0,"e":"Seas and gulfs take the.","h":"الخلجان تأخذ the."},{"n":26,"s":"If Noura ______ early, she will help us cook.","o":["will arrive","arrive","arrives","arrived"],"k":2,"e":"if-clause → present simple; she → arrives.","h":"جملة الشرط بالمضارع."},{"n":27,"s":"He stopped ______ sweets because they hurt his teeth.","o":["to eat","eating","eat","ate"],"k":1,"e":"stop (= quit) + -ing.","h":"stop بمعنى يتوقف عن + ing."},{"n":28,"s":"Who ______ the most important person in your life when you were a child?","o":["were","did","had","was"],"k":3,"e":"Who … was (singular).","h":"who مع was."},{"n":29,"s":"My grandparents ______ to Riyadh in 1990.","o":["have moved","move","moving","moved"],"k":3,"e":"Finished time (in 1990) → past simple.","h":"زمن ماضٍ محدد."},{"n":30,"s":"I think people ______ on Mars in the next fifty years.","o":["will live","are living","live","going to live"],"k":0,"e":"Opinion prediction → will.","h":"توقع برأي will."},{"n":31,"s":"Of all the subjects, science is the ______ for me.","o":["more interesting","interestingest","most interested","most interesting"],"k":3,"e":"Superlative of a long adjective.","h":"تفضيل الصفة الطويلة."},{"n":32,"s":"My cousin hasn't replied to my email ______.","o":["already","just","yet","ever"],"k":2,"e":"Negative + end → yet.","h":"yet في النهاية."},{"n":33,"s":"You ______ apologize to your teacher. You were rude.","o":["should","mustn't","don't have to","should to"],"k":0,"e":"Advice → should.","h":"النصيحة should."},{"n":34,"s":"There isn't ______ room in the car for another bag.","o":["many","much","a few","some of"],"k":1,"e":"room (space) is uncountable; negative → much.","h":"غير معدود في النفي much."},{"n":35,"s":"The road is too narrow ______ two buses to pass.","o":["to","for","that","enough"],"k":1,"e":"too + adjective + for + noun + to.","h":"too + for."}]},{"l":["Part B — Error Identification (Questions 36–50)"],"q":[{"n":36,"s":"(A) Was your friends (B) at the party (C) last (D) night?","o":["Was","at","last","night"],"k":0,"e":"your friends is plural → Were.","h":""},{"n":37,"s":"We (A) didn't (B) knew the (C) answer to the (D) last question.","o":["didn't","knew","answer","last"],"k":1,"e":"didn't + base form.","h":""},{"n":38,"s":"I (A) promise I (B) will (C) to call you (D) tonight.","o":["promise","will","to call","tonight"],"k":2,"e":"No to after will.","h":""},{"n":39,"s":"My brother (A) is more taller (B) than me (C) and (D) my sister.","o":["is more taller","than","and","my"],"k":0,"e":"No more with -er.","h":""},{"n":40,"s":"In this test (A) students (B) mustn't (C) to use (D) calculators.","o":["students","mustn't","to use","calculators"],"k":2,"e":"No to after mustn't.","h":""},{"n":41,"s":"She (A) has (B) visited Abha (C) twice (D) last year.","o":["has","visited","twice","last year"],"k":3,"e":"last year is finished time → past simple; or remove last year.","h":""},{"n":42,"s":"I need (A) some (B) informations about (C) the trip (D) to AlUla.","o":["some","informations","the","to"],"k":1,"e":"information is uncountable.","h":""},{"n":43,"s":"If you (A) will need help, (B) just (C) call (D) me.","o":["will need","just","call","me"],"k":0,"e":"No will in the if-clause.","h":""},{"n":44,"s":"My (A) uncle (B) avoids (C) to drive in the (D) city centre.","o":["uncle","avoids","to drive","city"],"k":2,"e":"avoid + -ing.","h":""},{"n":45,"s":"Where (A) did you (B) go after school, and what (C) did you (D) bought?","o":["did","go","did","bought"],"k":3,"e":"did + base form buy.","h":""},{"n":46,"s":"(A) Look! The baby (B) will fall off (C) the (D) bed!","o":["Look","will fall","the","bed"],"k":1,"e":"Evidence now → is going to.","h":""},{"n":47,"s":"Have you (A) already (B) had dinner, or (C) have you (D) forget?","o":["already","had","have","forget"],"k":3,"e":"have + past participle forgotten.","h":""},{"n":48,"s":"As soon as (A) I (B) will finish my work, (C) I'll (D) call you.","o":["I","will finish","I'll","call"],"k":1,"e":"After as soon as → present simple.","h":""},{"n":49,"s":"(A) The (B) life in the desert (C) is (D) difficult for many animals.","o":["The","life","is","difficult"],"k":0,"e":"General uncountable noun → no the.","h":""},{"n":50,"s":"This box is (A) too heavy (B) for me (C) carrying (D) alone.","o":["too","for me","carrying","alone"],"k":2,"e":"too + adjective + for + person + to + verb.","h":""}]}],"n":50}};
